# ---------- v23: окно не закрывается молча — ошибка видна и пишется в error.log ----------
def _log_err(text):
    try:
        with open("error.log", "a", encoding="utf-8") as _f: _f.write(time.strftime("%Y-%m-%d %H:%M:%S ") + text + "\n")
    except Exception: pass
def _pause(msg="Нажми Enter, чтобы закрыть окно..."):
    try:
        if sys.stdin and sys.stdin.isatty(): input("\n" + msg)
    except Exception: pass
def _hook(t, v, tb):
    import traceback
    txt = "".join(traceback.format_exception(t, v, tb)); print(txt); _log_err(txt)
    _pause("❌ Ошибка выше (она же записана в error.log). Нажми Enter, чтобы закрыть окно...")
sys.excepthook = _hook
if not hasattr(asyncio, "to_thread"):      # старый Python (3.8)
    async def _to_thread(f, *a, **k): return await asyncio.get_running_loop().run_in_executor(None, lambda: f(*a, **k))
    asyncio.to_thread = _to_thread

