def solve_weights(pool, target):
    def ev(a):
        w = [it["price"] ** -a for it in pool]
        return sum(x * it["price"] for x, it in zip(w, pool)) / sum(w)
    lo, hi = -6.0, 12.0
    for _ in range(80):
        mid = (lo + hi) / 2
        if ev(mid) > target: lo = mid
        else: hi = mid
    a = (lo + hi) / 2
    return [it["price"] ** -a for it in pool]

def solve_weights_win(pool, target, cost, p_win):
    """Веса так, чтобы средняя отдача = target И шанс выпасть предмету с ценой >= cost был p_win."""
    up = [it["price"] >= cost for it in pool]
    if not any(up) or all(up): return solve_weights(pool, target)
    def mk(a, g): return [(it["price"] ** -a) * (g if u else 1.0) for it, u in zip(pool, up)]
    def solve_a(g):
        lo, hi = -6.0, 12.0
        for _ in range(60):
            mid = (lo + hi) / 2; w = mk(mid, g)
            if sum(x * it["price"] for x, it in zip(w, pool)) / sum(w) > target: lo = mid
            else: hi = mid
        return (lo + hi) / 2
    def pw(g):
        w = mk(solve_a(g), g); return sum(x for x, u in zip(w, up) if u) / sum(w)
    lo, hi = math.log(1e-3), math.log(1e3)
    for _ in range(40):
        mid = (lo + hi) / 2
        if pw(math.exp(mid)) < p_win: lo = mid
        else: hi = mid
    g = math.exp((lo + hi) / 2)
    return mk(solve_a(g), g)

def _spread(cands, targets, theme=None, bonus=0.35):
    """Для каждой целевой цены берём ближайший свободный предмет (предметы по теме кейса получают бонус)."""
    used = set(); out = []
    for t in targets:
        best = None
        for k, it in enumerate(cands):
            if k in used: continue
            sc = abs(math.log(it["price"] / t)) - (bonus if theme and theme(it) else 0)
            if best is None or sc < best[0]: best = (sc, k)
        if best: used.add(best[1]); out.append(cands[best[1]])
    return out

def pick_pool(C, n, theme=None):
    """Набор предметов кейса: ~45% «окупных» (цена >= C, от C до ~8C) и остальные подешевле (от 0.1C до C) — чтобы был разброс."""
    up = [it for it in ITEMS if C <= it["price"] <= C * 10]
    dn = [it for it in ITEMS if C * MIN_DROP_PCT <= it["price"] < C]
    nu = min(len(up), max(1, math.ceil(n * CASE_UP_SHARE))); nd = min(len(dn), n - nu); nu = min(len(up), n - nd)
    tu = [C * math.exp(math.log(8) * (k / max(nu - 1, 1)) ** 1.3) for k in range(nu)]
    td = [C * math.exp(math.log(MIN_DROP_PCT) + (math.log(0.95) - math.log(MIN_DROP_PCT)) * k / max(nd - 1, 1)) for k in range(nd)]
    return sorted(_spread(up, tu, theme) + _spread(dn, td, theme), key=lambda it: it["price"])

def make_case(key, title, cost, n, kw):
    rx = re.compile(kw, re.I) if kw else None
    C = EXACT_CASE_PRICE.get(key) or round(cost * CASE_PRICE_MULT)
    pool = pick_pool(C, n, (lambda it: bool(rx.search(it["name"]))) if rx else None)
    if len(pool) < 3:   # в базе почти нет предметов рядом с этой ценой — старый способ подбора
        cand = sorted([it for it in ITEMS if it["price"] >= C * MIN_DROP_PCT] or ITEMS, key=lambda it: abs(math.log(it["price"] / max(C, 1)))); pool = sorted(cand[:n], key=lambda it: it["price"])
    target = max(C * CASE_RTP, pool[0]["price"] * 1.08)
    w = None
    for p in (CASE_WIN_CHANCE, 0.30, 0.25, 0.20, 0.15, 0.10, 0.0):   # если при таком шансе окупа средняя отдача выходит выше нормы — снижаем шанс
        w = solve_weights_win(pool, target, C, p) if p else solve_weights(pool, target)
        if sum(x * it["price"] for x, it in zip(w, pool)) / sum(w) <= target * 1.02: break
    return dict(key=key, title=title, cost=C, pool=pool, w=w)

