def print_case_report():
    """Таблица в консоль при старте: цена, сколько предметов окупаются, шанс окупа и средняя отдача."""
    print("📦 Кейсы: цена | предметов | окупных (цена >= кейса) | шанс окупа | средняя отдача")
    for k, c in CASES.items():
        if not c["cost"]: continue
        t = sum(c["w"]); pr = c["cost"]
        ok = sum(1 for it in c["pool"] if it["price"] >= pr); pw = sum(x for x, it in zip(c["w"], c["pool"]) if it["price"] >= pr) / t
        rtp = sum(x * it["price"] for x, it in zip(c["w"], c["pool"])) / t / pr
        print(f"   {k:11} {pr:>7} | {len(c['pool']):>2} | {ok:>2} | {pw*100:4.0f}% | {rtp*100:4.0f}%")
print_case_report()

