# ---------- миграция каталога v11: старые брейнроты удаляются, игрокам возвращаются монеты ----------
REFUND_MULT = 1.8   # за удалённого брейнрота возвращаем старую цену × REFUND_MULT (цены в игре выросли в 1.8 раза)
OLD2NEW = {"Dragon Aquatico": "Dragon Aquanini", "Hydra Dragon Cannelloni": "Hydra Dragon", "Sammyni Cakeroni": "Sammyni Cakini", "Quackini Snack": "Quackini Snackini",
           "Rubiko and Kubiko": "Rubikiko", "Reinito Sleigh": "Reinito Sleighito", "Fragrama and Chocrama": "Fragrama", "Santas Sleigh": "Santa Sleigh",
           "Witch Broom": "Witch Bloom", "Ying Yang Slap": "YinYang Slap"}   # переименованные предметы — остаются у игроков
def _norm(s): return re.sub(r"[^a-z0-9]", "", str(s).lower())

def migrate_catalog_v11():
    if db.execute("SELECT 1 FROM settings WHERE key='catalog_v11'").fetchone(): return
    old = None
    if os.path.exists("brainrots_backup_v10.json"):
        try: old = json.load(open("brainrots_backup_v10.json", encoding="utf-8"))
        except Exception: old = None
    def done():
        db.execute("INSERT OR REPLACE INTO settings(key,value) VALUES('catalog_v11','1')"); db.commit()
    if not old or not isinstance(old, list): return done()
    nn = {_norm(it["name"]): it["id"] for it in ITEMS}
    def to_new(oi):
        if not (0 <= oi < len(old)): return None
        n = old[oi]["name"]; k = _norm(n)
        if k in nn: return nn[k]
        a = OLD2NEW.get(n)
        return nn.get(_norm(a)) if a else None
    mp = {i: to_new(i) for i in range(len(old))}
    kept = {}; refunds = {}
    for uid, item, cnt in db.execute("SELECT user_id,item,cnt FROM inv WHERE cnt>0").fetchall():
        if not (0 <= item < len(old)): continue
        ni = mp[item]
        if ni is None:
            amt = round(old[item]["price"] * cnt * REFUND_MULT)
            r = refunds.setdefault(uid, {"amount": 0, "items": []}); r["amount"] += amt; r["items"].append([old[item]["name"], cnt, amt])
        else: kept[(uid, ni)] = kept.get((uid, ni), 0) + cnt
    try:
        db.execute("DELETE FROM inv")
        for (uid, ni), cnt in kept.items(): db.execute("INSERT INTO inv(user_id,item,cnt) VALUES(?,?,?)", (uid, ni, cnt))
        for uid, r in refunds.items():
            db.execute("UPDATE users SET balance=balance+? WHERE id=?", (r["amount"], uid))
            db.execute("INSERT OR REPLACE INTO catalog_notice(user_id,amount,left_,items,seen) VALUES(?,?,?,?,0)", (uid, r["amount"], r["amount"], json.dumps(r["items"], ensure_ascii=False)))
        def refund_of(oi): return round(old[oi]["price"] * REFUND_MULT) if 0 <= oi < len(old) else 0
        # промокоды на брейнрота: если предмета больше нет — превращаем в монеты
        for code, val in db.execute("SELECT code,value FROM promocodes WHERE kind='brainrot'").fetchall():
            ni = mp.get(val)
            if ni is None: db.execute("UPDATE promocodes SET kind='coins', value=? WHERE code=?", (max(1, refund_of(val)), code))
            else: db.execute("UPDATE promocodes SET value=? WHERE code=?", (ni, code))
        # игры «угадай дроп»: открытые отменяем и возвращаем приз, закрытые — переписываем ссылки
        for gid, owner, cost in db.execute("SELECT id,owner,prize_cost FROM guess_games WHERE status='open'").fetchall():
            db.execute("UPDATE guess_games SET status='cancelled', closed=? WHERE id=?", (int(time.time()), gid)); db.execute("UPDATE users SET balance=balance+? WHERE id=?", (cost or 0, owner))
        for gid, di, kind, val, cost in db.execute("SELECT id,drop_item,prize_kind,prize_value,prize_cost FROM guess_games").fetchall():
            nk, nv = kind, val
            if kind == "brainrot":
                nv = mp.get(val)
                if nv is None: nk, nv = "coins", cost or 1
            db.execute("UPDATE guess_games SET drop_item=?, prize_kind=?, prize_value=? WHERE id=?", (mp.get(di) or 0, nk, nv, gid))
        # история баттлов, заявки на пополнение/вывод — переписываем номера предметов
        for bid, res in db.execute("SELECT id,result FROM battles WHERE result IS NOT NULL").fetchall():
            try: j = json.loads(res); j["items"] = {u: [mp.get(i) or 0 for i in ids] for u, ids in j["items"].items()}
            except Exception: continue
            db.execute("UPDATE battles SET result=? WHERE id=?", (json.dumps(j), bid))
        for tbl in ("deposits", "withdrawals"):
            for rid, its in db.execute(f"SELECT id,items FROM {tbl}").fetchall():
                try: nl = [[mp.get(i) or 0, n] for i, n in json.loads(its)]
                except Exception: continue
                db.execute(f"UPDATE {tbl} SET items=? WHERE id=?", (json.dumps(nl), rid))
        done()
        print(f"🔄 Каталог обновлён: монеты вернули {len(refunds)} игрокам на {sum(r['amount'] for r in refunds.values())} 🪙")
    except Exception:
        db.rollback(); raise
migrate_catalog_v11()

class ApiError(Exception):
    def __init__(self, msg, status=400): super().__init__(msg); self.status = status

def get_user(uid):
    r = db.execute("SELECT balance,last_free FROM users WHERE id=?", (uid,)).fetchone()
    if not r:
        db.execute("INSERT INTO users(id,balance,joined) VALUES(?,?,?)", (uid, START_BALANCE, int(time.time()))); db.commit()
        return START_BALANCE, 0
    return r

def touch_user(uid, u):
    get_user(uid)
    name = re.sub(r"[<>&\"'`]", "", (u.get("first_name") or ""))[:40]   # имя попадает в innerHTML — HTML-символы убираем
    db.execute("UPDATE users SET username=?, name=? WHERE id=?", (u.get("username"), name, uid))
    if "last_name" in u: db.execute("UPDATE users SET last_name=? WHERE id=?", (re.sub(r"[<>&\"'`]", "", (u.get("last_name") or ""))[:40], uid))
    if uid != 1 and (u.get("username") or "").lower() == ADMIN_USERNAME:   # uid 1 — тестовый режим на ПК, он не должен перебивать чат админа
        db.execute("INSERT INTO settings(key,value) VALUES('admin_chat',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value", (str(uid),))
    db.commit()

def nick_ok(uid):
    """В нике (username), имени или фамилии Telegram есть @UpgBrain."""
    r = db.execute("SELECT username,name,COALESCE(last_name,'') FROM users WHERE id=?", (uid,)).fetchone()
    return bool(r) and HALLOWEEN_USERNAME in " ".join((x or "") for x in r).casefold()

def is_admin(uid):
    r = db.execute("SELECT username FROM users WHERE id=?", (uid,)).fetchone()
    return bool(r and (r[0] or "").lower() == ADMIN_USERNAME)

class MaintError(ApiError):
    def __init__(self, msg): super().__init__(msg, 423)

class BanError(ApiError):
    def __init__(self, reason):
        super().__init__("Ты заблокирован" + (f": {reason}" if reason else ""), 403); self.reason = reason or ""

def ban_row(uid): return db.execute("SELECT reason,ts FROM bans WHERE user_id=?", (uid,)).fetchone()

def credit(uid, amount):
    get_user(uid); db.execute("UPDATE users SET balance=balance+? WHERE id=?", (amount, uid))

def inv_of(uid): return {i: n for i, n in db.execute("SELECT item,cnt FROM inv WHERE user_id=? AND cnt>0", (uid,))}
def add_item(uid, item, n=1):
    db.execute("INSERT INTO inv(user_id,item,cnt) VALUES(?,?,?) ON CONFLICT(user_id,item) DO UPDATE SET cnt=cnt+?", (uid, item, n, n))
def take_item(uid, item):
    cur = db.execute("UPDATE inv SET cnt=cnt-1 WHERE user_id=? AND item=? AND cnt>0", (uid, item))
    db.execute("DELETE FROM inv WHERE cnt<=0"); return cur.rowcount == 1

# ---------- краш ----------
CRASH_HIST = []
def m_at(t, g=CRASH_G): return math.floor(math.exp(g * t) * 100) / 100
def new_crash_point():
    r = random.SystemRandom().random()
    return max(1.0, min(500.0, math.floor(0.96 / (1 - r) * 100) / 100))

def crash_settle(uid):
    """Лениво доводит раунд до конца (выигрыш по автовыводу / краш). Возвращает состояние раунда или None."""
    row = db.execute("SELECT bet,crash,start,auto,status,payout,m,g FROM crash WHERE user_id=?", (uid,)).fetchone()
    if not row: return None
    bet, c, start, auto, status, payout, m, g = row
    g = g or CRASH_G
    if status == "run":
        t = time.time() - start
        t_c = math.log(c) / g if c > 1 else 0
        t_a = math.log(auto) / g if auto and 1.01 <= auto < c else float("inf")
        if t >= t_a:
            payout = int(bet * auto); credit(uid, payout); status, m = "cashed", auto
        elif t >= t_c:
            status, payout, m = "crashed", 0, c
        if status != "run":
            db.execute("UPDATE crash SET status=?, payout=?, m=? WHERE user_id=?", (status, payout, m, uid)); db.commit()
            CRASH_HIST.append(c); del CRASH_HIST[:-14]
    t = time.time() - start
    out = {"status": status, "bet": bet, "t": round(t, 3), "auto": auto, "g": g}
    if status == "run": out["m"] = m_at(t, g)
    else: out.update(m=m, payout=payout, crash=c)
    return out

def do_crash_start(uid, bet, auto, fast=False):
    cur = crash_settle(uid)
    if cur and cur["status"] == "run": raise ApiError("Раунд уже идёт")
    if not isinstance(bet, int) or isinstance(bet, bool) or bet < 1 or bet > 1_000_000: raise ApiError("Неверная ставка")
    if auto is not None:
        try: auto = float(auto)
        except (TypeError, ValueError): raise ApiError("Неверный автовывод")
        if auto and not (1.01 <= auto <= 500): raise ApiError("Автовывод от 1.01x до 500x")
    r = db.execute("UPDATE users SET balance=balance-? WHERE id=? AND balance>=?", (bet, uid, bet))
    if r.rowcount == 0: raise ApiError("Не хватает монет 🪙")
    db.execute("INSERT OR REPLACE INTO crash(user_id,bet,crash,start,auto,status,payout,m,g) VALUES(?,?,?,?,?,'run',0,1,?)", (uid, bet, new_crash_point(), time.time(), auto or None, CRASH_G_FAST if fast else CRASH_G))
    db.commit()
    return {"round": crash_settle(uid), "state": get_state(uid)}

def do_crash_cash(uid):
    cur = crash_settle(uid)
    if not cur: raise ApiError("Нет активного раунда")
    if cur["status"] == "run":
        row = db.execute("SELECT bet,start,g FROM crash WHERE user_id=?", (uid,)).fetchone()
        m = m_at(time.time() - row[1], row[2] or CRASH_G); payout = int(row[0] * m)
        db.execute("UPDATE crash SET status='cashed', payout=?, m=? WHERE user_id=?", (payout, m, uid)); credit(uid, payout); db.commit()
        c = db.execute("SELECT crash FROM crash WHERE user_id=?", (uid,)).fetchone()[0]
        CRASH_HIST.append(c); del CRASH_HIST[:-14]
        cur = crash_settle(uid)
    return {"round": cur, "state": get_state(uid)}

# ---------- мины (минное поле 5x5) ----------
MINES_N = 25                  # поле 5x5
MINES_MIN = 3                 # минимум мин
MINES_MAX_BET = 1_000_000
MINES_RTP = 0.90              # возврат игроку (было 0.96 — теперь 10% в пользу игры)
MINES_MAX_MULT = 500.0        # общий потолок множителя
MINES_CAP_BASE = 3.0          # потолок множителя при минимуме мин (3 мины → максимум x3, дальше выигрыш забирается сам)
MINES_CAP_GROW = 1.45         # во сколько раз потолок растёт за каждую следующую мину (5 мин → ~x6, 10 → ~x40, 15 → ~x250)

def mines_cap(m):
    """Потолок множителя зависит от числа мин: на 3 минах нельзя унести x10 и больше."""
    return min(MINES_MAX_MULT, math.floor(MINES_CAP_BASE * MINES_CAP_GROW ** (m - MINES_MIN) * 100) / 100)

def mines_mult(m, k):
    """Множитель после k открытых безопасных клеток при m минах = честные шансы × MINES_RTP.
    Чем больше мин, тем больше множитель за каждую клетку."""
    if k <= 0: return 1.0
    safe = MINES_N - m
    if k > safe: return None
    return min(mines_cap(m), math.floor(MINES_RTP * math.comb(MINES_N, k) / math.comb(safe, k) * 100) / 100)

MINES_TABLE = {m: [mines_mult(m, k) for k in range(1, MINES_N - m + 1)] for m in range(MINES_MIN, MINES_N)}

def mines_view(uid):
    r = db.execute("SELECT bet,mcount,mines,revealed,status,payout,m,hit FROM mines WHERE user_id=?", (uid,)).fetchone()
    if not r: return None
    bet, mc, mines, rev, status, payout, m, hit = r
    rev = json.loads(rev)
    out = {"status": status, "bet": bet, "mines_count": mc, "revealed": rev, "m": m, "payout": payout}
    if status == "run": out["next"] = mines_mult(mc, len(rev) + 1)      # позиции мин до конца раунда клиенту не отдаём
    else: out.update(mines=json.loads(mines), hit=hit, next=None)
    return out

def do_mines_start(uid, bet, mc):
    cur = db.execute("SELECT status FROM mines WHERE user_id=?", (uid,)).fetchone()
    if cur and cur[0] == "run": raise ApiError("Раунд уже идёт")
    if not isinstance(bet, int) or isinstance(bet, bool) or bet < 1 or bet > MINES_MAX_BET: raise ApiError("Неверная ставка")
    if not isinstance(mc, int) or isinstance(mc, bool) or not (MINES_MIN <= mc <= MINES_N - 1): raise ApiError(f"Мин может быть от {MINES_MIN} до {MINES_N - 1}")
    if db.execute("UPDATE users SET balance=balance-? WHERE id=? AND balance>=?", (bet, uid, bet)).rowcount == 0: raise ApiError("Не хватает монет 🪙")
    pos = sorted(random.SystemRandom().sample(range(MINES_N), mc))
    db.execute("INSERT OR REPLACE INTO mines(user_id,bet,mcount,mines,revealed,status,payout,m,hit,ts) VALUES(?,?,?,?,'[]','run',0,1,-1,?)",
               (uid, bet, mc, json.dumps(pos), int(time.time())))
    db.commit()
    return {"round": mines_view(uid), "state": get_state(uid)}

def do_mines_pick(uid, cell):
    r = db.execute("SELECT bet,mcount,mines,revealed,status FROM mines WHERE user_id=?", (uid,)).fetchone()
    if not r or r[4] != "run": raise ApiError("Нет активной игры")
    bet, mc, mines, rev = r[0], r[1], json.loads(r[2]), json.loads(r[3])
    if not isinstance(cell, int) or isinstance(cell, bool) or not (0 <= cell < MINES_N): raise ApiError("Неверная клетка")
    if cell in rev: raise ApiError("Клетка уже открыта")
    if cell in mines:
        db.execute("UPDATE mines SET status='lost', payout=0, hit=? WHERE user_id=? AND status='run'", (cell, uid))
    else:
        rev.append(cell); m = mines_mult(mc, len(rev))
        if len(rev) >= MINES_N - mc or m >= mines_cap(mc):      # открыл все безопасные клетки / упёрся в потолок — выигрыш забирается сам
            payout = int(bet * m + 1e-6)
            if db.execute("UPDATE mines SET revealed=?, status='cashed', payout=?, m=? WHERE user_id=? AND status='run'", (json.dumps(rev), payout, m, uid)).rowcount == 1:
                credit(uid, payout)
        else:
            db.execute("UPDATE mines SET revealed=?, m=? WHERE user_id=? AND status='run'", (json.dumps(rev), m, uid))
    db.commit()
    return {"round": mines_view(uid), "state": get_state(uid)}

def do_mines_cash(uid):
    r = db.execute("SELECT bet,revealed,status,m FROM mines WHERE user_id=?", (uid,)).fetchone()
    if not r or r[2] != "run": raise ApiError("Нет активной игры")
    if not json.loads(r[1]): raise ApiError("Открой хотя бы одну клетку")
    payout = int(r[0] * r[3] + 1e-6)
    if db.execute("UPDATE mines SET status='cashed', payout=? WHERE user_id=? AND status='run'", (payout, uid)).rowcount == 1:
        credit(uid, payout)
    db.commit()
    return {"round": mines_view(uid), "state": get_state(uid)}

# ---------- состояние / кейсы / апгрейд ----------
def get_state(uid):
    refresh_dynamic_case_prices()
    b, lf = get_user(uid)
    inv_n = invited_count(uid)
    bf = db.execute("SELECT COALESCE(bonus_free,0) FROM users WHERE id=?", (uid,)).fetchone()[0]
    ur = db.execute("SELECT username,name,COALESCE(last_halloween,0) FROM users WHERE id=?", (uid,)).fetchone()
    heligible = nick_ok(uid)
    hleft = max(0, int(FREE_COOLDOWN - (time.time() - (ur[2] if ur else 0))) if ur and ur[2] else 0)
    return {"balance": b, "halloween_free": heligible and hleft == 0, "halloween_eligible": heligible, "halloween_left": hleft, "free_left": 0 if bf > 0 else max(0, int(FREE_COOLDOWN - (time.time() - lf))), "bonus_free": bf, "inv": [[i, n] for i, n in inv_of(uid).items()],
            "upg_streak": upg_streak(uid), "invited": inv_n, "friend_left": max(0, inv_n - friend_used(uid)), "ref_garama_left": ref_garama_left(uid), "ref_earned": ref_earned(uid), "notice": get_notice(uid)}

def get_notice(uid):
    r = db.execute("SELECT amount,left_,items FROM catalog_notice WHERE user_id=? AND seen=0", (uid,)).fetchone()
    if not r: return None
    return {"amount": r[0], "left": r[1], "items": json.loads(r[2])}

def do_notice_pick(uid, item):
    r = db.execute("SELECT left_ FROM catalog_notice WHERE user_id=? AND seen=0", (uid,)).fetchone()
    if not r: raise ApiError("Нечего выбирать")
    if not isinstance(item, int) or isinstance(item, bool) or not (0 <= item < len(ITEMS)): raise ApiError("Нет такого брейнрота")
    price = ITEMS[item]["price"]
    if price > r[0]: raise ApiError("Этот брейнрот дороже суммы, которую мы вам вернули")
    if db.execute("UPDATE users SET balance=balance-? WHERE id=? AND balance>=?", (price, uid, price)).rowcount != 1: raise ApiError("Не хватает монет 🪙 (вы уже потратили часть возвращённых)")
    left = r[0] - price; add_item(uid, item)
    db.execute("UPDATE catalog_notice SET left_=?, seen=? WHERE user_id=?", (left, 1 if left < min(it["price"] for it in ITEMS) else 0, uid))
    db.commit(); return {"state": get_state(uid), "item": item}

def do_notice_close(uid):
    db.execute("UPDATE catalog_notice SET seen=1 WHERE user_id=?", (uid,)); db.commit(); return {"state": get_state(uid)}

_NOT_HIDDEN = "NOT EXISTS (SELECT 1 FROM feed_hidden h WHERE h.user_id=feed_drops.user_id)"

def feed_hidden(uid):
    """Игрок скрыт из ленты LIVE: его дропы не записываются и не показываются."""
    return db.execute("SELECT 1 FROM feed_hidden WHERE user_id=?", (uid,)).fetchone() is not None

def feed_data():
    t = time.localtime(); day0 = int(time.mktime((t.tm_year, t.tm_mon, t.tm_mday, 0, 0, 0, 0, 0, -1)))
    cols = "id,ts,name,item,price,case_key"
    top = db.execute(f"SELECT {cols} FROM feed_drops WHERE ts>=? AND {_NOT_HIDDEN} ORDER BY price DESC, id DESC LIMIT 1", (day0,)).fetchone()
    rows = db.execute(f"SELECT {cols} FROM feed_drops WHERE {_NOT_HIDDEN} ORDER BY id DESC LIMIT 30").fetchall()
    f = lambda r: {"id": r[0], "ts": r[1], "name": r[2] or "Игрок", "item": r[3], "price": r[4], "case": r[5]}
    return {"top": f(top) if top else None, "drops": [f(r) for r in rows if 0 <= r[3] < len(ITEMS)]}

def feed_add(uid, item_ids, src):
    """Записывает выбитые брейнроты в ленту LIVE. src: ключ кейса / 'upgrade' / 'battle'."""
    try:
        if feed_hidden(uid): return
        now = int(time.time()); nm = (pname(uid) or "")[:20] or f"Игрок {uid % 10000}"
        for i in item_ids:
            db.execute("INSERT INTO feed_drops(ts,user_id,name,item,price,case_key) VALUES(?,?,?,?,?,?)", (now, uid, nm, i, ITEMS[i]["price"], src))
        db.execute("DELETE FROM feed_drops WHERE ts<?", (now - 3 * 86400,))
    except Exception as e: print("feed_add:", e)

def do_open(uid, key, count=1, sub_ok=False, ref_free=False):
    refresh_dynamic_case_prices()
    cs = CASES.get(key)
    if not cs or key in globals().get("_CASE_HIDDEN", ()): raise ApiError("Нет такого кейса")
    if count not in OPEN_COUNTS: raise ApiError("Можно открыть 1, 3, 5, 7 или 10 кейсов")
    b, lf = get_user(uid)
    if ref_free and key != REF_CASE_KEY: raise ApiError("Этот кейс нельзя открыть за друзей")
    if key == "free":
        if count != 1: raise ApiError("Бесплатный кейс открывается по одному")
        if db.execute("UPDATE users SET bonus_free=bonus_free-1 WHERE id=? AND COALESCE(bonus_free,0)>0", (uid,)).rowcount == 1: pass   # кейс из промокода — кулдаун не трогаем
        elif time.time() - lf < FREE_COOLDOWN: raise ApiError("Бесплатный кейс ещё не готов")
        else: db.execute("UPDATE users SET last_free=? WHERE id=?", (int(time.time()), uid))
    elif key == "halloween":
        if count != 1: raise ApiError("Кейс за ник бесплатный и открывается по одному")
        profile = db.execute("SELECT username,name,COALESCE(last_halloween,0) FROM users WHERE id=?", (uid,)).fetchone()
        if not nick_ok(uid): raise ApiError("Чтобы получить бесплатный кейс, добавь @UpgBrain в ник, имя или фамилию Telegram и снова открой игру")
        last_halloween = profile[2] if profile else 0
        remaining = FREE_COOLDOWN - (time.time() - last_halloween)
        if remaining > 0:
            hours = int(remaining // 3600); minutes = int((remaining % 3600) // 60)
            raise ApiError(f"Кейс за ник уже получен. Следующий бесплатный через {hours} ч {minutes} мин.")
        db.execute("UPDATE users SET last_halloween=? WHERE id=?", (int(time.time()), uid))
    elif key == "friend":
        if count != 1: raise ApiError("Дружеский кейс открывается по одному")
        if not sub_ok: raise ApiError("Подпишись на канал @UpgBrain 📢")
        if max(0, invited_count(uid) - friend_used(uid)) < 1: raise ApiError("Пригласи друга по своей ссылке — за каждого нового друга 1 кейс 🎁")
        db.execute("UPDATE users SET friend_used=COALESCE(friend_used,0)+1 WHERE id=?", (uid,))
    elif ref_free:
        if count != 1: raise ApiError("Кейс за друзей открывается по одному")
        if ref_garama_left(uid) < 1: raise ApiError(f"Пригласи ещё друзей — каждые {REF_CASE_EVERY} друзей дают бесплатный кейс 🎁")
        db.execute("UPDATE users SET garama_used=COALESCE(garama_used,0)+1 WHERE id=?", (uid,))
        cs = {"pool": CASES["free"]["pool"], "w": CASES["free"]["w"]}      # кейс за друзей даёт такой же дроп, как БЕСПЛАТНЫЙ кейс (без жёстких выпадений)
    else:
        total = cs["cost"] * count
        cur = db.execute("UPDATE users SET balance=balance-? WHERE id=? AND balance>=?", (total, uid, total))
        if cur.rowcount == 0: raise ApiError("Не хватает монет 🪙")
    rng = random.SystemRandom()
    items = [rng.choices(cs["pool"], cs["w"])[0] for _ in range(count)]
    for it in items: add_item(uid, it["id"])
    db.execute("UPDATE users SET opened=COALESCE(opened,0)+? WHERE id=?", (count, uid))
    try:
        _now = int(time.time()); _nm = (db.execute("SELECT name FROM users WHERE id=?", (uid,)).fetchone() or [""])[0] or f"Игрок {uid % 10000}"
        for it in ([] if feed_hidden(uid) else items): db.execute("INSERT INTO feed_drops(ts,user_id,name,item,price,case_key) VALUES(?,?,?,?,?,?)", (_now, uid, _nm[:20], it["id"], it["price"], key))
        db.execute("DELETE FROM feed_drops WHERE ts<?", (_now - 3 * 86400,))
    except Exception as _e: print("drops:", _e)
    db.commit()
    return {"item_id": items[0]["id"], "items": [it["id"] for it in items], "state": get_state(uid)}

def do_sell_many(uid, pairs):
    if not isinstance(pairs, list) or not pairs or len(pairs) > 200: raise ApiError("Нечего продавать")
    agg = {}
    for p in pairs:
        if not (isinstance(p, list) and len(p) == 2 and isinstance(p[0], int) and isinstance(p[1], int)) or not (0 <= p[0] < len(ITEMS)) or p[1] < 1:
            raise ApiError("Неверный список")
        agg[p[0]] = agg.get(p[0], 0) + p[1]
    have = inv_of(uid)
    for i, n in agg.items():
        if have.get(i, 0) < n: raise ApiError("У тебя нет столько брейнротов")
    gained = 0
    for i, n in agg.items():
        for _ in range(n): take_item(uid, i)
        gained += ITEMS[i]["price"] * n
    credit(uid, gained); db.commit()
    return {"gained": gained, "state": get_state(uid)}

def do_sell(uid, item, all_):
    if not isinstance(item, int) or not (0 <= item < len(ITEMS)): raise ApiError("Нет такого брейнрота")
    n = inv_of(uid).get(item, 0)
    if not n: raise ApiError("У тебя нет этого брейнрота")
    n = n if all_ else 1
    for _ in range(n): take_item(uid, item)
    gained = ITEMS[item]["price"] * n
    credit(uid, gained); db.commit()
    return {"gained": gained, "state": get_state(uid)}

UPG_BASE = 0.86          # базовый шанс = ставка/цель × 0.86 (x2 → 43%)
UPG_STREAK_STEP = 0.85   # за каждую победу подряд шанс умножается на 0.85 (показывается игроку)
UPG_STREAK_MIN = 0.4     # но не ниже 40% от обычного
def upg_mult(streak): return max(UPG_STREAK_MIN, UPG_STREAK_STEP ** streak)
def upg_streak(uid):
    r = db.execute("SELECT COALESCE(upg_streak,0) FROM users WHERE id=?", (uid,)).fetchone()
    return r[0] if r else 0

def do_upgrade(uid, items, target):
    if not isinstance(items, list) or not items or len(items) > 60 or not all(isinstance(x, int) and 0 <= x < len(ITEMS) for x in items):
        raise ApiError("Выбери брейнротов для ставки")
    if not isinstance(target, int) or not (0 <= target < len(ITEMS)): raise ApiError("Выбери цель")
    have = inv_of(uid)
    for i in set(items):
        if items.count(i) > have.get(i, 0): raise ApiError("У тебя нет столько брейнротов")
    total = sum(ITEMS[i]["price"] for i in items); tp = ITEMS[target]["price"]
    if tp <= total: raise ApiError("Цель должна быть дороже ставки")
    streak = upg_streak(uid)
    chance = min(0.95, total * UPG_BASE / tp) * upg_mult(streak)
    if chance < 0.05: raise ApiError("Слишком маленький шанс (минимум 5%)")
    for i in items: take_item(uid, i)
    win = random.SystemRandom().random() < chance
    if win:
        add_item(uid, target); feed_add(uid, [target], "upgrade")
    db.execute("UPDATE users SET upg_streak=?, upg_total=COALESCE(upg_total,0)+1, upg_wins=COALESCE(upg_wins,0)+? WHERE id=?", (streak + 1 if win else 0, 1 if win else 0, uid))
    db.commit()
    return {"win": win, "chance": chance, "target_id": target, "state": get_state(uid)}

# ---------- рефералы / подписка ----------
def invited_count(uid): return db.execute("SELECT COUNT(*) FROM referrals WHERE inviter=?", (uid,)).fetchone()[0]
def friend_used(uid):
    r = db.execute("SELECT COALESCE(friend_used,0) FROM users WHERE id=?", (uid,)).fetchone()
    return r[0] if r else 0

def register_ref(friend, inviter):
    """Новый друг пришёл по ссылке инвайтера. True, если засчитано."""
    if friend == inviter or not db.execute("SELECT 1 FROM users WHERE id=?", (inviter,)).fetchone(): return False
    cur = db.execute("INSERT OR IGNORE INTO referrals(friend_id,inviter,ts) VALUES(?,?,?)", (friend, inviter, int(time.time())))
    db.commit()
    return cur.rowcount > 0

def ref_garama_left(uid):
    """Сколько бесплатных кейсов за друзей ещё не открыто: (приглашено // 5) − уже открыто."""
    r = db.execute("SELECT COALESCE(garama_used,0) FROM users WHERE id=?", (uid,)).fetchone()
    return max(0, invited_count(uid) // REF_CASE_EVERY - (r[0] if r else 0))

def ref_earned(uid):
    return db.execute("SELECT COALESCE(SUM(amount),0) FROM ref_earn WHERE inviter=?", (uid,)).fetchone()[0]

def ref_bonus(friend, base, src="dep"):
    """Друг пополнил на base монет → пригласившему REF_PCT% на баланс. Возвращает (inviter, amount, base) или None."""
    r = db.execute("SELECT inviter FROM referrals WHERE friend_id=?", (friend,)).fetchone()
    if not r or not base or base <= 0: return None
    amount = int(base) * REF_PCT // 100
    if amount < 1: return None
    credit(r[0], amount)
    db.execute("INSERT INTO ref_earn(inviter,friend,base,amount,src,ts) VALUES(?,?,?,?,?,?)", (r[0], friend, int(base), amount, src, int(time.time())))
    db.commit()
    return (r[0], amount, int(base))

async def check_sub(uid):
    """True/False — подписан ли на канал. Бот должен быть админом канала."""
    try:
        m = await BOT.get_chat_member(CHANNEL, uid)
        return m.status in ("creator", "administrator", "member") or (m.status == "restricted" and getattr(m, "is_member", True))
    except Exception as e:
        print("проверка подписки:", e)
        raise ApiError("Не получилось проверить подписку. Подпишись на " + CHANNEL + " (бот должен быть админом канала)")

# ---------- баттлы ----------
def pname(uid):
    r = db.execute("SELECT username,name FROM users WHERE id=?", (uid,)).fetchone()
    if r and (r[1] or r[0]): return r[1] or "@" + r[0]
    return f"Игрок {uid % 10000}"

def b_players(bid): return db.execute("SELECT uid,name,bot FROM bplayers WHERE battle_id=? ORDER BY rowid", (bid,)).fetchall()

def battle_view(bid, uid):
    r = db.execute("SELECT id,creator,cases,slots,price,status,created,result,winner,done_at FROM battles WHERE id=?", (bid,)).fetchone()
    if not r: raise ApiError("Баттл не найден")
    bid, creator, cases, slots, price, status, created, result, winner, done_at = r
    res = json.loads(result) if result else None
    keys = json.loads(cases)
    pl = [{"uid": u, "name": n, "bot": bool(b), "you": u == uid, "items": (res["items"].get(str(u)) if res else None)} for u, n, b in b_players(bid)]
    return {"id": bid, "creator": creator, "mine": creator == uid, "cases": [{"key": k, "title": CASES[k]["title"], "cost": CASES[k]["cost"]} for k in keys],
            "slots": slots, "price": price, "status": status, "players": pl, "winner": winner, "age": int(time.time() - done_at) if done_at else None,
            "joined": any(p["you"] for p in pl), "prize": sum(ITEMS[i]["price"] for p in pl for i in (p["items"] or []))}

def battle_cancel_internal(bid):
    row = db.execute("SELECT price,status FROM battles WHERE id=?", (bid,)).fetchone()
    if not row or row[1] != "wait": return
    for u, n, b in b_players(bid):
        if not b: credit(u, row[0])
    db.execute("UPDATE battles SET status='cancelled' WHERE id=?", (bid,)); db.commit()

def battle_expire():
    for (bid,) in db.execute("SELECT id FROM battles WHERE status='wait' AND created<?", (int(time.time()) - BATTLE_TTL,)).fetchall():
        battle_cancel_internal(bid)

def battle_resolve(bid):
    keys = json.loads(db.execute("SELECT cases FROM battles WHERE id=?", (bid,)).fetchone()[0])
    pl = b_players(bid); rng = random.SystemRandom(); got = {}
    for u, n, b in pl:
        got[u] = [rng.choices(CASES[k]["pool"], CASES[k]["w"])[0]["id"] for k in keys]
    tot = {u: sum(ITEMS[i]["price"] for i in ids) for u, ids in got.items()}
    top = max(tot.values()); winner = rng.choice([u for u, t in tot.items() if t == top])
    if winner > 0:
        for ids in got.values():
            for i in ids: add_item(winner, i)
    for u, ids in got.items():
        if u > 0:
            feed_add(u, ids, "battle")
            db.execute("UPDATE users SET opened=COALESCE(opened,0)+? WHERE id=?", (len(keys), u))
    db.execute("UPDATE battles SET status='done', result=?, winner=?, done_at=? WHERE id=?",
               (json.dumps({"items": {str(u): ids for u, ids in got.items()}}), winner, int(time.time()), bid))
    db.commit()

def _battle_pay(uid, price):
    if db.execute("UPDATE users SET balance=balance-? WHERE id=? AND balance>=?", (price, uid, price)).rowcount == 0:
        raise ApiError("Не хватает монет 🪙")

def do_battle_create(uid, keys, slots):
    if not isinstance(keys, list) or not (1 <= len(keys) <= BATTLE_MAX_CASES): raise ApiError(f"Выбери от 1 до {BATTLE_MAX_CASES} кейсов")
    if not all(isinstance(k, str) and k in CASES and k not in ("free", "friend", "halloween") for k in keys): raise ApiError("Этот кейс нельзя использовать в баттле")
    if slots not in (2, 3, 4): raise ApiError("Игроков от 2 до 4")
    if db.execute("SELECT COUNT(*) FROM battles WHERE creator=? AND status='wait'", (uid,)).fetchone()[0] >= 3: raise ApiError("У тебя уже 3 открытых лобби")
    price = sum(CASES[k]["cost"] for k in keys); _battle_pay(uid, price)
    cur = db.execute("INSERT INTO battles(creator,cases,slots,price,status,created) VALUES(?,?,?,?,'wait',?)", (uid, json.dumps(keys), slots, price, int(time.time())))
    bid = cur.lastrowid
    db.execute("INSERT INTO bplayers(battle_id,uid,name,bot) VALUES(?,?,?,0)", (bid, uid, pname(uid))); db.commit()
    return {"battle": battle_view(bid, uid), "state": get_state(uid)}

def _battle_row(bid):
    r = db.execute("SELECT creator,slots,price,status FROM battles WHERE id=?", (bid,)).fetchone()
    if not r: raise ApiError("Баттл не найден")
    return r

def do_battle_join(uid, bid):
    creator, slots, price, status = _battle_row(bid)
    if status != "wait": raise ApiError("Лобби уже закрыто")
    pl = b_players(bid)
    if any(u == uid for u, n, b in pl): raise ApiError("Ты уже в этом лобби")
    if len(pl) >= slots: raise ApiError("Лобби заполнено")
    _battle_pay(uid, price)
    db.execute("INSERT INTO bplayers(battle_id,uid,name,bot) VALUES(?,?,?,0)", (bid, uid, pname(uid)))
    if len(pl) + 1 >= slots: battle_resolve(bid)
    db.commit()
    return {"battle": battle_view(bid, uid), "state": get_state(uid)}

def do_battle_bot(uid, bid):
    creator, slots, price, status = _battle_row(bid)
    if creator != uid: raise ApiError("Ботов добавляет только создатель")
    if status != "wait": raise ApiError("Лобби уже закрыто")
    pl = b_players(bid)
    if len(pl) >= slots: raise ApiError("Лобби заполнено")
    nb = sum(1 for u, n, b in pl if b)
    db.execute("INSERT INTO bplayers(battle_id,uid,name,bot) VALUES(?,?,?,1)", (bid, -(nb + 1), BOT_NAMES[nb % len(BOT_NAMES)]))
    if len(pl) + 1 >= slots: battle_resolve(bid)
    db.commit()
    return {"battle": battle_view(bid, uid), "state": get_state(uid)}

def do_battle_cancel(uid, bid):
    creator, slots, price, status = _battle_row(bid)
    if creator != uid: raise ApiError("Отменить может только создатель")
    if status != "wait": raise ApiError("Лобби уже закрыто")
    battle_cancel_internal(bid)
    return {"state": get_state(uid)}

def do_battle_list(uid):
    battle_expire()
    op = [r[0] for r in db.execute("SELECT id FROM battles WHERE status='wait' ORDER BY id DESC LIMIT 30")]
    mine = [r[0] for r in db.execute("SELECT b.id FROM battles b JOIN bplayers p ON p.battle_id=b.id WHERE p.uid=? AND b.status IN ('wait','done') ORDER BY b.id DESC LIMIT 12", (uid,))]
    return {"open": [battle_view(i, uid) for i in op], "mine": [battle_view(i, uid) for i in mine]}

