# ---------- тиктокеры ----------
def tt_row(uid): return db.execute("SELECT user_id,ref_code,added FROM tiktokers WHERE user_id=?", (uid,)).fetchone()
def is_tt(uid): return tt_row(uid) is not None
def need_tt(uid):
    if not is_tt(uid): raise ApiError("Только для тиктокеров", 403)

def dep_promo_all(): return {r[0]: r[1] for r in db.execute("SELECT code,pct FROM dep_promos").fetchall()}
def dep_promo_use(code):
    if code: db.execute("UPDATE dep_promos SET used=used+1 WHERE code=?", (str(code).strip().upper(),))

def code_taken(code):
    return (code in dep_promo_all() or db.execute("SELECT 1 FROM promocodes WHERE code=?", (code,)).fetchone() is not None
            or db.execute("SELECT 1 FROM tiktokers WHERE ref_code=?", (code,)).fetchone() is not None)

def tt_log(tt_id, user_id, base, cut):
    """Игрок пополнил по коду тиктокера: пишем в журнал и (если включено) начисляем тиктокеру долю."""
    if not tt_id or not is_tt(tt_id): return False
    if cut > 0: credit(tt_id, cut)
    db.execute("INSERT INTO tt_uses(tt_id,user_id,base,cut,ts) VALUES(?,?,?,?,?)", (tt_id, user_id, base, cut, int(time.time())))
    return True

async def notify_tt(tt_id, code, base, cut):
    if not BOT: return
    try: await BOT.send_message(tt_id, f"🎬 Игрок пополнил баланс по твоему промокоду {code}: {base} 🪙" + (f"\n💸 Тебе начислено {cut} 🪙" if cut else ""))
    except Exception: pass

def promo_info(uid, code):
    """-> (процент бонуса игроку, id тиктокера или None). Бросает ApiError, если код не подходит."""
    code = (code or "").strip().upper()
    if not code: return 0, None
    tt = None
    _dp = db.execute("SELECT pct,active FROM dep_promos WHERE code=?", (code,)).fetchone()
    if _dp:
        if not _dp[1]: raise ApiError("Промокод сейчас выключен")
        pct = _dp[0]
    else:
        r = db.execute("SELECT user_id FROM tiktokers WHERE ref_code=?", (code,)).fetchone()
        if not r: raise ApiError("Неверный промокод")
        if r[0] == uid: raise ApiError("Нельзя использовать свой собственный промокод")
        pct, tt = TT_PLAYER_PCT, r[0]
    return pct, tt          # промокод к пополнению можно использовать сколько угодно раз

def promo_pct(uid, code): return promo_info(uid, code)[0]

def dep_day_map():
    return {r[0]: r[1] for r in db.execute("SELECT item,pct FROM dep_day").fetchall()}

def setting_get(k, d=None):
    r = db.execute("SELECT value FROM settings WHERE key=?", (k,)).fetchone()
    return r[0] if r else d
def setting_set(k, v):
    db.execute("INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value", (k, str(v))); db.commit()
# ---------- v28: редактор кейсов (админка → 📦 Кейсы) ----------
_CASE_FIX = set()      # кейсы с ценой, заданной админом (динамическая цена не перезаписывает)
_CASE_HIDDEN = set()   # скрытые от игроков кейсы
_CASE_DEFAULT = {k: dict(c) for k, c in CASES.items()}
def _ce_load():
    try: d = json.loads(setting_get("case_edit", "{}") or "{}")
    except Exception: d = {}
    return d if isinstance(d, dict) else {}
def _ce_save(d): setting_set("case_edit", json.dumps(d, ensure_ascii=False))
def _ce_apply_one(key, e):
    pool = []; w = []
    for pair in (e.get("items") or []):
        try: i, ch = int(pair[0]), float(pair[1])
        except Exception: continue
        if 0 <= i < len(ITEMS) and ch > 0: pool.append(ITEMS[i]); w.append(ch)
    c = CASES.get(key) or dict(key=key, title="", cost=0, pool=[], w=[])
    if e.get("title"): c["title"] = str(e["title"])[:24]
    if e.get("cost") is not None:
        c["cost"] = int(e["cost"])
        if key in _CASE_DEFAULT and _CASE_DEFAULT[key]["cost"] != 0 or key == "fire": _CASE_FIX.add(key)
    if len(pool) >= 2: c["pool"] = pool; c["w"] = w
    if len(c["pool"]) >= 2: CASES[key] = c
def apply_case_edits():
    d = _ce_load()
    for key, e in (d.get("edit") or {}).items():
        if key in _CASE_DEFAULT and isinstance(e, dict): _ce_apply_one(key, e)
    for key, e in (d.get("custom") or {}).items():
        if isinstance(e, dict): _ce_apply_one(key, e)
    _CASE_HIDDEN.clear(); _CASE_HIDDEN.update(k for k in (d.get("hidden") or []) if k in CASES)
try: apply_case_edits()
except Exception as _e: print("case_edit:", _e)
def _ce_info(key):
    c = CASES[key]; t = sum(c["w"]) or 1; d = _ce_load()
    return {"key": key, "title": c["title"], "cost": c["cost"], "custom": key not in _CASE_DEFAULT, "hidden": key in _CASE_HIDDEN,
            "edited": key in (d.get("edit") or {}), "photo": bool((d.get("photos") or {}).get(key)), "tag": _tag_of(key, d), "items": [{"id": it["id"], "chance": round(w / t * 100, 4)} for it, w in zip(c["pool"], c["w"])]}
async def h_adm_cases(r):
    uid = auth(r); need_admin(uid); refresh_dynamic_case_prices()
    return J({"cases": [_ce_info(k) for k in CASES]})
async def h_adm_case_save(r):
    uid = auth(r); need_admin(uid); b = await body(r)
    key = b.get("key") or ""; title = str(b.get("title") or "").strip()[:24]
    if not title: raise ApiError("Введи название кейса")
    new = not key
    if new:
        key = "c" + str(int(time.time()))
        while key in CASES: key += "x"
    elif key not in CASES: raise ApiError("Нет такого кейса", 404)
    free = (not new) and key in _CASE_DEFAULT and _CASE_DEFAULT[key]["cost"] == 0
    try: cost = 0 if free else int(b.get("cost"))
    except Exception: raise ApiError("Неверная цена")
    if not free and not (1 <= cost <= 10000000): raise ApiError("Цена — от 1 до 10 000 000 монет")
    raw = b.get("items")
    if not isinstance(raw, list) or not (2 <= len(raw) <= 80): raise ApiError("В кейсе должно быть от 2 до 80 брейнротов")
    seen = set(); items = []
    for x in raw:
        try: i = int(x["id"]); ch = float(x["chance"])
        except Exception: raise ApiError("Неверные данные брейнротов")
        if not (0 <= i < len(ITEMS)): raise ApiError("Такого брейнрота нет в каталоге")
        if i in seen: raise ApiError("Один брейнрот добавлен дважды")
        if not (0 < ch < 1e9): raise ApiError("У «" + ITEMS[i]["name"] + "» шанс должен быть больше 0")
        seen.add(i); items.append([i, ch])
    d = _ce_load(); sect = "edit" if key in _CASE_DEFAULT else "custom"
    d.setdefault(sect, {})[key] = {"title": title, "cost": cost, "items": items}
    _ce_save(d); _ce_apply_one(key, d[sect][key])
    return J({"ok": True, "case": _ce_info(key)})

async def h_adm_case_photo(r):
    uid = auth(r); need_admin(uid); b = await body(r); key = str(b.get("key") or "")
    if key not in CASES: raise ApiError("Нет такого кейса", 404)
    data = str(b.get("data") or "")
    m = re.fullmatch(r"data:image/webp;base64,([A-Za-z0-9+/=]+)", data)
    if not m: raise ApiError("Загрузи изображение WebP")
    try: raw = base64.b64decode(m.group(1), validate=True)
    except Exception: raise ApiError("Повреждённый файл изображения")
    if len(raw) > 2 * 1024 * 1024: raise ApiError("Изображение должно быть не больше 2 МБ")
    if len(raw) < 16 or raw[:4] != b"RIFF" or raw[8:12] != b"WEBP":
        raise ApiError("Файл не является изображением WebP")
    os.makedirs("cases", exist_ok=True)
    with open(os.path.join("cases", key + "_custom.webp"), "wb") as f: f.write(raw)
    d = _ce_load(); d.setdefault("photos", {})[key] = True; _ce_save(d)
    return J({"ok": True, "photo": True})

async def h_adm_case_photo_delete(r):
    uid = auth(r); need_admin(uid); b = await body(r); key = str(b.get("key") or "")
    if key not in CASES: raise ApiError("Нет такого кейса", 404)
    path = os.path.join("cases", key + "_custom.webp")
    try:
        if os.path.isfile(path): os.remove(path)
    except OSError as e: raise ApiError("Не удалось удалить изображение: " + str(e))
    d = _ce_load(); (d.get("photos") or {}).pop(key, None); _ce_save(d)
    return J({"ok": True, "photo": False})

async def h_adm_case_reset(r):
    uid = auth(r); need_admin(uid); b = await body(r); key = b.get("key")
    if key not in _CASE_DEFAULT: raise ApiError("Сбросить можно только стандартный кейс")
    d = _ce_load(); (d.get("edit") or {}).pop(key, None); _ce_save(d)
    CASES[key] = dict(_CASE_DEFAULT[key]); _CASE_FIX.discard(key)
    return J({"ok": True})
async def h_adm_case_hide(r):
    uid = auth(r); need_admin(uid); b = await body(r); key = b.get("key")
    if key not in CASES: raise ApiError("Нет такого кейса", 404)
    d = _ce_load(); hid = set(d.get("hidden") or [])
    if b.get("hidden"): hid.add(key)
    else: hid.discard(key)
    d["hidden"] = sorted(hid); _ce_save(d); _CASE_HIDDEN.clear(); _CASE_HIDDEN.update(hid)
    return J({"ok": True})

# ---------- v28: метки на кейсах (Обновлён / Новый / Хит ...) ----------
TAG_COLORS = {"#ffe45c", "#ff4f8b", "#14b86a", "#4fa8ff", "#c04dff", "#ff8a3d", "#14b8a6"}
def _tag_of(key, d=None):
    d = d if d is not None else _ce_load(); t = (d.get("tags") or {}).get(key)
    if not isinstance(t, dict) or not t.get("t"): return None
    if t.get("until") and t["until"] < time.time(): return None
    return {"t": t["t"], "c": t.get("c") or "#ffe45c", "until": t.get("until", 0)}
async def h_adm_case_tag(r):
    uid = auth(r); need_admin(uid); b = await body(r); key = b.get("key")
    if key not in CASES: raise ApiError("Нет такого кейса", 404)
    t = str(b.get("t") or "").strip()[:14]; d = _ce_load(); tags = d.setdefault("tags", {})
    if not t: tags.pop(key, None)
    else:
        col = b.get("c") if b.get("c") in TAG_COLORS else "#ffe45c"
        try: days = float(b.get("days") or 0)
        except Exception: days = 0
        days = max(0.0, min(days, 365.0))
        tags[key] = {"t": t, "c": col, "until": int(time.time() + days * 86400) if days else 0}
    _ce_save(d)
    return J({"ok": True, "tag": _tag_of(key, d)})

def dep_open():
    """Пополнение открыто? Админ может временно закрыть из профиля → Админка."""
    return setting_get("dep_open", "1") == "1"
def wd_open():
    """Вывод открыт? Пока админ не трогал переключатель — берём WITHDRAW_ENABLED из начала файла."""
    v = setting_get("wd_open")
    return WITHDRAW_ENABLED if v is None else v == "1"
MSG_DEP_CLOSED = "Пополнение временно закрыто. Следи за новостями @UpgBrain 📢"
MSG_WD_CLOSED = "Вывод временно закрыт. Следи за новостями @UpgBrain 📢"
MSG_BOT_CLOSED = "🔧 Бот временно закрыт на технические работы. Скоро вернёмся! Следи за новостями @UpgBrain 📢"
db.execute("CREATE TABLE IF NOT EXISTS dep_block(item INTEGER PRIMARY KEY)")   # v25: брейнроты, которые админ запретил принимать в пополнение
def dep_block_set():
    return {r[0] for r in db.execute("SELECT item FROM dep_block").fetchall()}
# ---------- v30: депозит, нужный для вывода каждого брейнрота ----------
db.execute("CREATE TABLE IF NOT EXISTS wd_req(item INTEGER PRIMARY KEY, dep INTEGER NOT NULL)")   # индивидуальный депозит (переопределяет формулу)
def wd_default_req(price):
    """По умолчанию: брейнрот за 150 → депозит 80, дальше растёт вместе с ценой."""
    return max(1, int(round(WD_DEP_BASE * (price / WD_MIN_ITEM) ** WD_DEP_POW / 5.0)) * 5)
def wd_req_map():
    """{id брейнрота: нужный депозит} только для брейнротов, которые вообще можно вывести."""
    ov = {r[0]: r[1] for r in db.execute("SELECT item,dep FROM wd_req").fetchall()}
    return {i: ov.get(i, wd_default_req(it["price"])) for i, it in enumerate(ITEMS) if it["price"] >= WD_MIN_ITEM}
def user_deposited(uid):
    """Сколько монет игрок реально пополнил: выполненные заявки брейнротами + звёзды (без бонусов)."""
    a = db.execute("SELECT COALESCE(SUM(total),0) FROM deposits WHERE user_id=? AND status='done'", (uid,)).fetchone()[0]
    s = db.execute("SELECT COALESCE(SUM(stars),0) FROM payments WHERE user_id=?", (uid,)).fetchone()[0]
    return int(a) + int(s) * STAR_RATE
def bot_open():
    """Бот открыт для игроков? Админ может временно закрыть (Профиль → Админка или /close в боте). Админа это не касается."""
    return setting_get("bot_open", "1") == "1"
def bot_msg():
    return setting_get("bot_msg", "") or MSG_BOT_CLOSED

def do_deposit_brainrots(uid, nick, items, code):
    if not dep_open(): raise ApiError(MSG_DEP_CLOSED)
    nick = (nick or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9_]{3,20}", nick): raise ApiError("Введи свой ник в Roblox (3–20 символов: буквы, цифры, _)")
    if not isinstance(items, list) or not items or len(items) > 60: raise ApiError("Выбери брейнротов")
    agg = {}; blk = dep_block_set()
    for x in items:
        i, n = (x.get("id"), x.get("n")) if isinstance(x, dict) else (None, None)      # FIX: не-словарь в списке давал 500
        if not isinstance(i, int) or not (0 <= i < len(ITEMS)) or not isinstance(n, int) or not (1 <= n <= 100): raise ApiError("Неверный список брейнротов")
        if ITEMS[i]["price"] < MIN_DEPOSIT_ITEM: raise ApiError(f"Брейнротов дешевле {MIN_DEPOSIT_ITEM} монет для пополнения не принимаем")
        if i in blk: raise ApiError(f"«{ITEMS[i]['name']}» сейчас не принимается для пополнения. Убери его из заявки")
        agg[i] = agg.get(i, 0) + n
    total = sum(ITEMS[i]["price"] * n for i, n in agg.items())
    if total < MIN_DEPOSIT: raise ApiError(f"Минимум для пополнения — {MIN_DEPOSIT} монет")
    if db.execute("SELECT COUNT(*) FROM deposits WHERE user_id=? AND status IN ('new','contacted')", (uid,)).fetchone()[0] >= 3:
        raise ApiError("У тебя уже 3 активные заявки. Дождись админа")
    pct, tt = promo_info(uid, code); promo_bonus = total * pct // 100
    dm = dep_day_map(); day_bonus = sum(ITEMS[i]["price"] * n * dm[i] // 100 for i, n in agg.items() if dm.get(i))   # бонус только за выбранные админом брейнроты дня
    bonus = promo_bonus + day_bonus
    cut = total * TT_CUT_PCT // 100 if tt else 0
    ref = (code or "").strip().upper() if (pct or tt) else None
    cur = db.execute("INSERT INTO deposits(user_id,nick,items,total,promo,bonus,status,created,ref_code,tt_id,tt_cut,day_bonus) VALUES(?,?,?,?,?,?,'new',?,?,?,?,?)",
                     (uid, nick, json.dumps([[i, n] for i, n in agg.items()]), total, pct, bonus, int(time.time()), ref, tt, cut, day_bonus))
    if pct: dep_promo_use(code)
    db.commit()
    return {"id": cur.lastrowid, "total": total, "bonus": bonus, "day_bonus": day_bonus}

def dep_row(r):
    return {"id": r[0], "user_id": r[1], "nick": r[2], "items": json.loads(r[3]), "total": r[4], "promo": r[5], "bonus": r[6], "status": r[7], "created": r[8], "when": r[9],
            "username": r[10] if len(r) > 10 else None, "name": r[11] if len(r) > 11 else None,
            "ref_code": r[12] if len(r) > 12 else None, "tt_id": r[13] if len(r) > 13 else None, "tt_cut": r[14] if len(r) > 14 else 0, "day_bonus": r[15] if len(r) > 15 else 0}
DEP_COLS = "d.id,d.user_id,d.nick,d.items,d.total,d.promo,d.bonus,d.status,d.created,d.when_text,u.username,u.name,d.ref_code,d.tt_id,d.tt_cut,d.day_bonus"

def credit_stars(uid, stars, promo_flag, charge_id, code=""):
    if db.execute("SELECT 1 FROM payments WHERE charge_id=?", (charge_id,)).fetchone(): return None
    coins = stars * STAR_RATE; pct = 0; tt = None; cut = 0
    if promo_flag:
        try: pct, tt = promo_info(uid, code or "OCTOBER")      # старые счета без кода — это OCTOBER
        except ApiError: pct, tt = 0, None
        if pct: dep_promo_use(code or "OCTOBER")
    bonus = coins * pct // 100
    credit(uid, coins + bonus)
    if tt:
        cut = coins * TT_CUT_PCT // 100
        if not tt_log(tt, uid, coins, cut): tt = None; cut = 0
    db.execute("INSERT INTO payments(charge_id,user_id,stars,coins,ts) VALUES(?,?,?,?,?)", (charge_id, uid, stars, coins + bonus, int(time.time())))
    db.commit()
    return coins, bonus, tt, cut

# ---------- вывод брейнротов ----------
def wd_row(r):
    return {"id": r[0], "user_id": r[1], "nick": r[2], "items": json.loads(r[3]), "total": r[4], "status": r[5], "created": r[6], "when": r[7],
            "username": r[8] if len(r) > 8 else None, "name": r[9] if len(r) > 9 else None}
WD_COLS = "w.id,w.user_id,w.nick,w.items,w.total,w.status,w.created,w.when_text,u.username,u.name"

def do_withdraw(uid, nick, items):
    if not wd_open(): raise ApiError(MSG_WD_CLOSED)
    nick = (nick or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9_]{3,20}", nick): raise ApiError("Введи свой ник в Roblox (3–20 символов: буквы, цифры, _)")
    if not isinstance(items, list) or not items or len(items) > 60: raise ApiError("Выбери брейнротов для вывода")
    agg = {}
    for x in items:
        i, n = (x.get("id"), x.get("n")) if isinstance(x, dict) else (None, None)
        if not isinstance(i, int) or not (0 <= i < len(ITEMS)) or not isinstance(n, int) or not (1 <= n <= 100): raise ApiError("Неверный список брейнротов")
        agg[i] = agg.get(i, 0) + n
    for i in agg:
        if ITEMS[i]["price"] < WD_MIN_ITEM: raise ApiError(f"Выводить можно брейнротов от {WD_MIN_ITEM} монет: «{ITEMS[i]['name']}» дешевле")
    if sum(ITEMS[i]["price"] * n for i, n in agg.items()) < MIN_WITHDRAW: raise ApiError(f"Минимум для вывода — {MIN_WITHDRAW} монет")
    rm = wd_req_map(); need = max(rm[i] for i in agg); dep = user_deposited(uid)
    if dep < need:
        worst = max(agg, key=lambda i: rm[i])
        raise ApiError(f"Для вывода «{ITEMS[worst]['name']}» нужен депозит {need} 🪙, у тебя {dep} 🪙. Пополни ещё на {need - dep} 🪙")
    if db.execute("SELECT COUNT(*) FROM withdrawals WHERE user_id=? AND status IN ('new','contacted')", (uid,)).fetchone()[0] >= 3:
        raise ApiError("У тебя уже 3 активные заявки на вывод. Дождись админа")
    have = inv_of(uid)
    for i, n in agg.items():
        if have.get(i, 0) < n: raise ApiError("У тебя нет столько брейнротов")
    for i, n in agg.items():          # брейнроты сразу списываются (резерв), при отказе возвращаются
        for _ in range(n): take_item(uid, i)
    total = sum(ITEMS[i]["price"] * n for i, n in agg.items())
    cur = db.execute("INSERT INTO withdrawals(user_id,nick,items,total,status,created) VALUES(?,?,?,?,'new',?)",
                     (uid, nick, json.dumps([[i, n] for i, n in agg.items()]), total, int(time.time())))
    db.commit()
    return {"id": cur.lastrowid, "total": total, "state": get_state(uid)}

# ---------- промокоды (монеты / брейнрот / бесплатный кейс) ----------
PROMO_KINDS = ("coins", "brainrot", "case")
def promo_view(r):
    return {"code": r[0], "kind": r[1], "value": r[2], "max_uses": r[3], "used": r[4], "created": r[5], "active": bool(r[6]),
            "owner": r[7] if len(r) > 7 else None, "owner_name": (("@" + r[8]) if r[8] else None) if len(r) > 8 else None,
            "refund": (r[9] * max(0, r[3] - r[4])) if len(r) > 9 else 0, "posted": bool(r[10]) if len(r) > 10 else False}

def do_redeem(uid, code):
    code = re.sub(r"\s+", "", str(code or "")).upper()
    if not code: raise ApiError("Введи промокод")
    row = db.execute("SELECT code,kind,value,max_uses,used,created,active FROM promocodes WHERE code=?", (code,)).fetchone()
    if not row or not row[6]: raise ApiError("Неверный промокод")
    if db.execute("SELECT 1 FROM promo_uses WHERE code=? AND user_id=?", (code, uid)).fetchone(): raise ApiError("Ты уже активировал этот промокод")
    if db.execute("UPDATE promocodes SET used=used+1 WHERE code=? AND used<max_uses", (code,)).rowcount != 1: raise ApiError("Промокод закончился — все активации использованы")
    db.execute("INSERT INTO promo_uses(code,user_id,ts) VALUES(?,?,?)", (code, uid, int(time.time())))
    kind, val = row[1], row[2]
    if kind == "coins": credit(uid, val); msg = f"+{val} 🪙"
    elif kind == "brainrot":
        if not (0 <= val < len(ITEMS)): raise ApiError("Ошибка промокода: брейнрот не найден")
        add_item(uid, val); msg = f"Брейнрот «{ITEMS[val]['name']}» в инвентаре!"
    else:
        db.execute("UPDATE users SET bonus_free=COALESCE(bonus_free,0)+? WHERE id=?", (val, uid)); msg = f"Бесплатный кейс ×{val} 🎁 — открой его во вкладке «Кейсы»"
    db.commit()
    return {"msg": msg, "kind": kind, "value": val, "state": get_state(uid)}

def do_promo_create(code, kind, value, max_uses, owner=None):
    code = re.sub(r"\s+", "", str(code or "")).upper()
    if not re.fullmatch(r"[A-Z0-9_\-]{3,24}", code): raise ApiError("Код: 3–24 символа, латиница, цифры, _ или -")
    if kind not in PROMO_KINDS: raise ApiError("Неверный тип промокода")
    if not isinstance(value, int) or isinstance(value, bool): raise ApiError("Неверное значение")
    if kind == "coins" and not (1 <= value <= 1_000_000): raise ApiError("Монеты: от 1 до 1 000 000")
    if kind == "brainrot" and not (0 <= value < len(ITEMS)): raise ApiError("Выбери брейнрота")
    if kind == "case" and not (1 <= value <= 100): raise ApiError("Кейсов: от 1 до 100")
    if not isinstance(max_uses, int) or isinstance(max_uses, bool) or not (1 <= max_uses <= 1_000_000): raise ApiError("Активаций: от 1 до 1 000 000")
    if code in dep_promo_all() or db.execute("SELECT 1 FROM tiktokers WHERE ref_code=?", (code,)).fetchone(): raise ApiError("Этот код занят бонусом к пополнению")
    unit = 0
    if owner is not None:      # тиктокер платит за награду СВОИМ балансом, всё списывается сразу
        if kind not in ("coins", "brainrot"): raise ApiError("Тиктокеры могут создавать промокоды на монеты или брейнрота")
        unit = value if kind == "coins" else ITEMS[value]["price"]
        cost = unit * max_uses
        if db.execute("UPDATE users SET balance=balance-? WHERE id=? AND balance>=?", (cost, owner, cost)).rowcount != 1:
            db.rollback(); raise ApiError(f"Не хватает монет: нужно {cost} 🪙 ({unit} × {max_uses}), они спишутся с твоего баланса")
    try: db.execute("INSERT INTO promocodes(code,kind,value,max_uses,created,owner,unit_cost) VALUES(?,?,?,?,?,?,?)", (code, kind, value, max_uses, int(time.time()), owner, unit))
    except sqlite3.IntegrityError: db.rollback(); raise ApiError("Такой промокод уже есть")
    db.commit()
    return {"ok": True, "code": code, "cost": unit * max_uses}

def promo_delete(code, owner=None):
    """Удаляет промокод. Если его создал тиктокер — неиспользованные активации возвращаются ему на баланс."""
    row = db.execute("SELECT owner,unit_cost,max_uses,used FROM promocodes WHERE code=?", (code,)).fetchone()
    if not row: raise ApiError("Промокод не найден", 404)
    if owner is not None and row[0] != owner: raise ApiError("Это не твой промокод", 403)
    refund = row[1] * max(0, row[2] - row[3]) if row[0] else 0
    db.execute("DELETE FROM promocodes WHERE code=?", (code,)); db.execute("DELETE FROM promo_uses WHERE code=?", (code,))
    if refund: credit(row[0], refund)
    db.commit()
    return refund

# ---------- канал: пост про промокод + мини-игра «Что выпадет» ----------
def promo_reward_text(kind, val):
    if kind == "coins": return f"{val} 🪙"
    if kind == "brainrot" and isinstance(val, int) and 0 <= val < len(ITEMS): return f"🧠 {ITEMS[val]['name']} ({ITEMS[val]['price']} 🪙)"
    return f"🎁 бесплатный кейс ×{val}"

def promo_post_text(code):
    import html as _h
    r = db.execute("SELECT kind,value,max_uses,used,active FROM promocodes WHERE code=?", (code,)).fetchone()
    if not r: return None
    kind, val, mx, used, act = r; left = max(0, mx - used)
    filled = round(left / mx * 10) if mx else 0
    bar = "🟩" * filled + "⬜" * (10 - filled)
    status = "❌ <b>Все активации использованы — промокод закончился</b>" if left == 0 else "⏸ Промокод временно выключен" if not act else "🔥 Успей активировать!"
    return (f"🎟 <b>ПРОМОКОД</b>\n\n🔑 Код: <code>{_h.escape(code)}</code>\n🎁 Награда: <b>{_h.escape(promo_reward_text(kind, val))}</b> за активацию\n"
            f"👥 Активаций всего: <b>{mx}</b>\n✅ Осталось: <b>{left}</b> из {mx}\n{bar}\n\n{status}\n\n"
            f"📲 Как активировать: открой игру → Инвентарь → «🎟 Промокод».\n1 игрок — 1 раз.")

def _promo_kb():
    from aiogram.types import InlineKeyboardMarkup, InlineKeyboardButton
    if not BOT_USERNAME: return None
    return InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="🎮 Открыть игру", url=f"https://t.me/{BOT_USERNAME}")]])

async def promo_post_create(code):
    """Выкладывает пост в канал. Возвращает None при успехе или текст ошибки."""
    if BOT is None: return "бот не запущен"
    txt = promo_post_text(code)
    if not txt: return "промокод не найден"
    try: m = await BOT.send_message(CHANNEL, txt, parse_mode="HTML", reply_markup=_promo_kb(), disable_web_page_preview=True)
    except Exception as e: return f"{type(e).__name__}: {str(e)[:140]} (бот должен быть админом канала {CHANNEL})"
    db.execute("UPDATE promocodes SET tg_msg=? WHERE code=?", (m.message_id, code)); db.commit()
    return None

async def promo_post_update(code):
    if BOT is None: return
    r = db.execute("SELECT tg_msg FROM promocodes WHERE code=?", (code,)).fetchone()
    txt = promo_post_text(code)
    if not r or not r[0] or not txt: return
    try: await BOT.edit_message_text(txt, chat_id=CHANNEL, message_id=r[0], parse_mode="HTML", reply_markup=_promo_kb(), disable_web_page_preview=True)
    except Exception as e:
        if "not modified" not in str(e).lower(): print("⚠️ пост промокода:", str(e)[:120])

_PP = set()
def promo_post_schedule(code):
    """Обновить пост в канале (не чаще раза в 2 сек на промокод — чтобы не упереться в лимиты Telegram)."""
    if code in _PP or BOT is None: return
    r = db.execute("SELECT tg_msg FROM promocodes WHERE code=?", (code,)).fetchone()
    if not r or not r[0]: return
    _PP.add(code)
    async def _run():
        await asyncio.sleep(2); _PP.discard(code); await promo_post_update(code)
    asyncio.create_task(_run())

# ---- мини-игра «Что выпадет» ----
GAME_MAX_OPEN = 3
GAME_BAD_CASES = ("free", "friend", "halloween")
_GCOLS = "id,owner,title,case_key,drop_item,prize_kind,prize_value,prize_cost,status,created,closed,winner"

def prize_text(kind, val):
    if kind == "coins": return f"{val} 🪙"
    return f"🧠 {ITEMS[val]['name']}" if isinstance(val, int) and 0 <= val < len(ITEMS) else "?"
def game_link(gid): return f"https://t.me/{BOT_USERNAME}?start=g_{gid}" if BOT_USERNAME else ""
def game_get(gid):
    if not isinstance(gid, int) or isinstance(gid, bool): return None
    r = db.execute(f"SELECT {_GCOLS} FROM guess_games WHERE id=?", (gid,)).fetchone()
    return dict(zip(_GCOLS.split(","), r)) if r else None
def uname(uid):
    r = db.execute("SELECT username,name FROM users WHERE id=?", (uid,)).fetchone() if uid else None
    return (("@" + r[0]) if r and r[0] else (r[1] if r and r[1] else "Игрок"))

def do_game_create(owner, title, case_key, kind, value):
    title = re.sub(r"\s+", " ", str(title or "")).strip()[:40]
    refresh_dynamic_case_prices(); cs = CASES.get(case_key) if isinstance(case_key, str) else None
    if not cs or case_key in GAME_BAD_CASES or not cs["cost"]: raise ApiError("Выбери платный кейс")
    if kind not in ("coins", "brainrot"): raise ApiError("Приз: монеты или брейнрот")
    if not isinstance(value, int) or isinstance(value, bool): raise ApiError("Неверный приз")
    if kind == "coins" and not (1 <= value <= 1_000_000): raise ApiError("Монеты: от 1 до 1 000 000")
    if kind == "brainrot" and not (0 <= value < len(ITEMS)): raise ApiError("Выбери брейнрота")
    if db.execute("SELECT COUNT(*) FROM guess_games WHERE owner=? AND status='open'", (owner,)).fetchone()[0] >= GAME_MAX_OPEN:
        raise ApiError(f"Одновременно можно держать до {GAME_MAX_OPEN} игр — заверши или отмени одну")
    cost = value if kind == "coins" else ITEMS[value]["price"]
    if db.execute("UPDATE users SET balance=balance-? WHERE id=? AND balance>=?", (cost, owner, cost)).rowcount != 1:
        db.rollback(); raise ApiError(f"Не хватает монет: приз стоит {cost} 🪙, он спишется с твоего баланса")
    drop = random.SystemRandom().choices(cs["pool"], cs["w"])[0]["id"]        # результат выбирает сервер и скрывает до «Показать результат»
    cur = db.execute("INSERT INTO guess_games(owner,title,case_key,drop_item,prize_kind,prize_value,prize_cost,status,created) VALUES(?,?,?,?,?,?,?,'open',?)",
                     (owner, title, case_key, drop, kind, value, cost, int(time.time())))
    db.commit(); return cur.lastrowid

def do_game_finish(gid, owner):
    g = game_get(gid)
    if not g or g["owner"] != owner: raise ApiError("Игра не найдена", 404)
    if db.execute("UPDATE guess_games SET status='done', closed=? WHERE id=? AND status='open'", (int(time.time()), gid)).rowcount != 1: raise ApiError("Игра уже завершена")
    w = db.execute("SELECT user_id FROM guess_votes WHERE game_id=? AND item=? ORDER BY id LIMIT 1", (gid, g["drop_item"])).fetchone()   # первый, кто выбрал верный ответ
    winner = w[0] if w else None
    if winner:
        if g["prize_kind"] == "coins": credit(winner, g["prize_value"])
        else: add_item(winner, g["prize_value"])
        db.execute("UPDATE guess_games SET winner=? WHERE id=?", (winner, gid))
    else: credit(owner, g["prize_cost"])            # никто не угадал — приз возвращается создателю
    db.commit(); return g, winner

def do_game_cancel(gid, owner):
    g = game_get(gid)
    if not g or g["owner"] != owner: raise ApiError("Игра не найдена", 404)
    if db.execute("UPDATE guess_games SET status='cancelled', closed=? WHERE id=? AND status='open'", (int(time.time()), gid)).rowcount != 1: raise ApiError("Игра уже закрыта")
    credit(owner, g["prize_cost"]); db.commit(); return g

def do_game_vote(uid, gid, item):
    g = game_get(gid)
    if not g: raise ApiError("Игра не найдена", 404)
    if g["status"] != "open": raise ApiError("Голосование уже закончено")
    if uid == g["owner"]: raise ApiError("Создатель не может голосовать в своей игре")
    if not isinstance(item, int) or isinstance(item, bool) or item not in {it["id"] for it in CASES[g["case_key"]]["pool"]}: raise ApiError("Такого варианта нет")
    try: db.execute("INSERT INTO guess_votes(game_id,user_id,item,ts) VALUES(?,?,?,?)", (gid, uid, item, int(time.time())))
    except sqlite3.IntegrityError: db.rollback(); raise ApiError("Ты уже проголосовал")
    db.commit()

def game_votes(gid): return db.execute("SELECT COUNT(*) FROM guess_votes WHERE game_id=?", (gid,)).fetchone()[0]

def tt_games(uid):
    out = []
    for r in db.execute(f"SELECT {_GCOLS} FROM guess_games WHERE owner=? ORDER BY id DESC LIMIT 15", (uid,)).fetchall():
        g = dict(zip(_GCOLS.split(","), r))
        e = {"id": g["id"], "title": g["title"], "case": g["case_key"], "status": g["status"], "prize": {"kind": g["prize_kind"], "value": g["prize_value"]},
             "votes": game_votes(g["id"]), "link": game_link(g["id"]), "created": g["created"]}
        if g["status"] == "done": e["drop"] = g["drop_item"]; e["winner"] = uname(g["winner"]) if g["winner"] else None
        out.append(e)
    return out

# ---- мини-игра «Спины» (рулетка: подписчики заходят по ссылке, рулетка выбирает победителя) ----
SPIN_MAX_OPEN = 3            # сколько спинов партнёр может держать открытыми одновременно
SPIN_MAX_PLAYERS = 2000      # максимум участников в одном спине
db.execute("CREATE TABLE IF NOT EXISTS spin_games(id INTEGER PRIMARY KEY AUTOINCREMENT, owner INTEGER, title TEXT, prize_kind TEXT, prize_value INTEGER, prize_cost INTEGER, status TEXT, created INTEGER, closed INTEGER, winner INTEGER, spun_at INTEGER)")
db.execute("CREATE TABLE IF NOT EXISTS spin_players(game_id INTEGER, user_id INTEGER, ts INTEGER, PRIMARY KEY(game_id,user_id))")
db.commit()
_SCOLS = "id,owner,title,prize_kind,prize_value,prize_cost,status,created,closed,winner,spun_at"

def spin_link(sid): return f"https://t.me/{BOT_USERNAME}?start=s_{sid}" if BOT_USERNAME else ""
def spin_get(sid):
    if not isinstance(sid, int) or isinstance(sid, bool): return None
    r = db.execute(f"SELECT {_SCOLS} FROM spin_games WHERE id=?", (sid,)).fetchone()
    return dict(zip(_SCOLS.split(","), r)) if r else None
def spin_count(sid): return db.execute("SELECT COUNT(*) FROM spin_players WHERE game_id=?", (sid,)).fetchone()[0]

def do_spin_create(owner, title, kind, value):
    title = re.sub(r"\s+", " ", str(title or "")).strip()[:40]
    if kind not in ("coins", "brainrot"): raise ApiError("Приз: монеты или брейнрот")
    if not isinstance(value, int) or isinstance(value, bool): raise ApiError("Неверный приз")
    if kind == "coins" and not (1 <= value <= 1_000_000): raise ApiError("Монеты: от 1 до 1 000 000")
    if kind == "brainrot" and not (0 <= value < len(ITEMS)): raise ApiError("Выбери брейнрота")
    if db.execute("SELECT COUNT(*) FROM spin_games WHERE owner=? AND status='open'", (owner,)).fetchone()[0] >= SPIN_MAX_OPEN:
        raise ApiError(f"Одновременно можно держать до {SPIN_MAX_OPEN} спинов — запусти или отмени один")
    cost = value if kind == "coins" else ITEMS[value]["price"]
    if db.execute("UPDATE users SET balance=balance-? WHERE id=? AND balance>=?", (cost, owner, cost)).rowcount != 1:
        db.rollback(); raise ApiError(f"Не хватает монет: приз стоит {cost} 🪙, он спишется с твоего баланса")
    cur = db.execute("INSERT INTO spin_games(owner,title,prize_kind,prize_value,prize_cost,status,created) VALUES(?,?,?,?,?,'open',?)",
                     (owner, title, kind, value, cost, int(time.time())))
    db.commit(); return cur.lastrowid

def do_spin_join(uid, sid):
    g = spin_get(sid)
    if not g: raise ApiError("Спин не найден", 404)
    if g["status"] != "open": raise ApiError("Набор участников уже закончен")
    if uid == g["owner"]: raise ApiError("Создатель не может участвовать в своём спине")
    if spin_count(sid) >= SPIN_MAX_PLAYERS: raise ApiError("Мест больше нет")
    try: db.execute("INSERT INTO spin_players(game_id,user_id,ts) VALUES(?,?,?)", (sid, uid, int(time.time())))
    except sqlite3.IntegrityError: db.rollback(); raise ApiError("Ты уже участвуешь")
    db.commit()

def do_spin_run(sid, owner):
    g = spin_get(sid)
    if not g or g["owner"] != owner: raise ApiError("Спин не найден", 404)
    now = int(time.time())
    if db.execute("UPDATE spin_games SET status='done', closed=?, spun_at=? WHERE id=? AND status='open'", (now, now, sid)).rowcount != 1:
        db.rollback(); raise ApiError("Спин уже завершён")
    players = [r[0] for r in db.execute("SELECT user_id FROM spin_players WHERE game_id=? ORDER BY ts, rowid", (sid,)).fetchall()]
    winner = random.SystemRandom().choice(players) if players else None      # победителя выбирает сервер, честный случайный выбор среди всех участников
    if winner:
        if g["prize_kind"] == "coins": credit(winner, g["prize_value"])
        else: add_item(winner, g["prize_value"])
        db.execute("UPDATE spin_games SET winner=? WHERE id=?", (winner, sid))
    else: credit(owner, g["prize_cost"])            # участников не было — приз возвращается создателю
    db.commit(); return g, winner, len(players)

def do_spin_cancel(sid, owner):
    g = spin_get(sid)
    if not g or g["owner"] != owner: raise ApiError("Спин не найден", 404)
    if db.execute("UPDATE spin_games SET status='cancelled', closed=? WHERE id=? AND status='open'", (int(time.time()), sid)).rowcount != 1:
        db.rollback(); raise ApiError("Спин уже закрыт")
    credit(owner, g["prize_cost"]); db.commit(); return g

def tt_spins(uid):
    out = []
    for r in db.execute(f"SELECT {_SCOLS} FROM spin_games WHERE owner=? ORDER BY id DESC LIMIT 15", (uid,)).fetchall():
        g = dict(zip(_SCOLS.split(","), r))
        e = {"id": g["id"], "title": g["title"], "status": g["status"], "prize": {"kind": g["prize_kind"], "value": g["prize_value"]},
             "count": spin_count(g["id"]), "link": spin_link(g["id"]), "created": g["created"]}
        if g["status"] == "done": e["winner"] = uname(g["winner"]) if g["winner"] else None
        out.append(e)
    return out


# ---------- веб ----------
_AUTH_LOG = {}
def _auth_log(reason, request):
    now = time.time()
    if now - _AUTH_LOG.get(reason, 0) < 5: return      # не спамим консоль
    _AUTH_LOG[reason] = now
    h = request.headers
    print(f"⚠️ auth: {reason} | {request.method} {request.path} | через туннель: {'да' if ('X-Forwarded-For' in h or 'Cf-Connecting-Ip' in h) else 'нет'} | {h.get('User-Agent', '')[:80]}")

def _tg_hash_ok(d, h):
    secret = hmac.new(b"WebAppData", TOKEN.encode(), hashlib.sha256).digest()
    for skip in ((), ("signature",)):   # по документации hash считается по всем полям, кроме hash; на всякий случай пробуем и без signature
        check = "\n".join(f"{k}={v}" for k, v in sorted(d.items()) if k not in skip)
        if hmac.compare_digest(hmac.new(secret, check.encode(), hashlib.sha256).hexdigest(), h): return True
    return False

def auth(request):
    init = request.headers.get("X-Init-Data", "")
    if init:
        d = dict(parse_qsl(init, keep_blank_values=True)); h = d.pop("hash", None)
        if not h or not _tg_hash_ok(d, h):
            _auth_log("подпись initData не сошлась — токен в token.txt не от того бота, через которого открыли игру?", request)
            raise ApiError("Ошибка авторизации Telegram. Закрой игру и открой заново кнопкой «🎮 Играть» в боте", 401)
        try:
            age = time.time() - int(d.get("auth_date", 0)); u = json.loads(d["user"]); uid = int(u["id"])
        except (KeyError, ValueError, TypeError):
            _auth_log("в initData нет данных пользователя", request)
            raise ApiError("Telegram не передал данные пользователя. Открой игру кнопкой «🎮 Играть» в боте", 401)
        if age > AUTH_MAX_AGE:
            _auth_log(f"initData устарел ({int(age / 3600)} ч) — проверь дату и время на ПК", request)
            raise ApiError("Сессия устарела. Закрой игру полностью и открой заново кнопкой «🎮 Играть» в боте", 401)
    else:
        # тест из обычного браузера: только напрямую с этого компьютера (не через туннель)
        if "X-Forwarded-For" in request.headers or "Cf-Connecting-Ip" in request.headers or request.remote not in ("127.0.0.1", "::1"):
            _auth_log("нет initData — игру открыли не из Telegram (ссылка из браузера?) или Telegram не передал данные", request)
            raise ApiError("Игра открыта не через Telegram. Открой бота и нажми «🎮 Играть»", 401)
        u = {"id": 1, "first_name": "Тест", "username": "momiksTV"}
    touch_user(u["id"], u)
    if not is_admin(u["id"]):
        _b = ban_row(u["id"])
        if _b: raise BanError(_b[0])
        if not bot_open(): raise MaintError(bot_msg())      # v25: бот закрыт — игроков не пускаем (админа пускаем)
    return u["id"]

