_VISIT_RL = {}
_HDR_SKIP = {"cookie", "authorization", "x-init-data"}
def client_ip(r):
    h = r.headers
    ip = h.get("Cf-Connecting-Ip") or (h.get("X-Forwarded-For", "").split(",")[0].strip()) or h.get("X-Real-Ip") or (r.remote or "")
    return ip[:64]
async def h_visit(r):
    """Сайт открыли НЕ из Telegram (нет initData) — сохраняем всё, что отдал браузер + заголовки запроса."""
    ip = client_ip(r); now = time.time()
    _VISIT_RL[ip] = [t for t in _VISIT_RL.get(ip, []) if now - t < 60]
    if len(_VISIT_RL[ip]) >= 5: return J({"ok": True})          # анти-спам: не больше 5 записей в минуту с одного IP
    _VISIT_RL[ip].append(now)
    if len(_VISIT_RL) > 5000: _VISIT_RL.clear()
    try: raw = await r.json()
    except Exception: raw = {}
    cl = raw if isinstance(raw, dict) else {}
    cl = json.loads(json.dumps(cl, ensure_ascii=False)[:6000]) if len(json.dumps(cl, ensure_ascii=False)) <= 6000 else {"truncated": True}
    hd = {k: v[:300] for k, v in r.headers.items() if k.lower() not in _HDR_SKIP}
    vid = str(cl.get("vid", ""))[:40]
    country = (r.headers.get("Cf-Ipcountry") or "")[:8]
    db.execute("INSERT INTO web_visits(ts,vid,ip,country,ua,lang,referer,path,client,headers) VALUES(?,?,?,?,?,?,?,?,?,?)",
               (int(now), vid, ip, country, r.headers.get("User-Agent", "")[:400], r.headers.get("Accept-Language", "")[:200],
                (cl.get("referrer") or r.headers.get("Referer", ""))[:400], str(cl.get("href", ""))[:400],
                json.dumps(cl, ensure_ascii=False), json.dumps(hd, ensure_ascii=False)))
    db.commit()
    local = ip in ("127.0.0.1", "::1") and "X-Forwarded-For" not in r.headers and "Cf-Connecting-Ip" not in r.headers
    if not local:
        scr = cl.get("screen") or {}
        asyncio.create_task(notify_admin(f"🌐 Заход на сайт не из Telegram\nIP: {ip} {country}\nУстройство: {cl.get('platform','?')} · {scr.get('w','?')}x{scr.get('h','?')}\nЯзык: {cl.get('lang','?')} · пояс: {cl.get('tz','?')}\nОткуда: {(cl.get('referrer') or 'напрямую')[:100]}\nПодробности — Админ-панель → 🌐 Заходы"))
    return J({"ok": True})
