def _find_users(q):
    """Поиск по ВСЕМ игрокам: id, @username, имя, фамилия. Регистр не важен (в т.ч. кириллица)."""
    q = (q or "").strip().lstrip("@").casefold()
    if not q: return []
    hits = []
    for uid_, un, nm, ln in db.execute("SELECT id,username,name,COALESCE(last_name,'') FROM users").fetchall():
        un_, nm_, ln_ = (un or "").casefold(), (nm or "").casefold(), (ln or "").casefold()
        if q == str(uid_) or q == un_: rank = 0
        elif str(uid_).startswith(q) or un_.startswith(q) or nm_.startswith(q): rank = 1
        elif q in str(uid_) or q in un_ or q in nm_ or q in ln_ or q in f"{nm_} {ln_}": rank = 2
        else: continue
        hits.append((rank, uid_))
    hits.sort(); return [u for _, u in hits]

async def h_adm_players(r):
    uid = auth(r); need_admin(uid)
    q = (r.query.get("q") or "").strip()
    sel = ("SELECT u.id,u.username,u.name,u.balance,(SELECT COALESCE(SUM(cnt),0) FROM inv WHERE user_id=u.id),"
           "(SELECT COUNT(*) FROM deposits WHERE user_id=u.id),b.reason FROM users u LEFT JOIN bans b ON b.user_id=u.id")
    total = db.execute("SELECT COUNT(*) FROM users").fetchone()[0]
    if q:
        ids = _find_users(q); found = len(ids); ids = ids[:100]
        rows = db.execute(sel + " WHERE u.id IN (%s)" % ",".join("?" * len(ids)), ids).fetchall() if ids else []
        order = {u: i for i, u in enumerate(ids)}; rows.sort(key=lambda x: order.get(x[0], 0))
    else:
        found = total
        rows = db.execute(sel + " ORDER BY u.balance DESC LIMIT 200").fetchall()
    return J({"total": total, "found": found, "query": q,
              "players": [{"id": x[0], "username": x[1], "name": x[2], "balance": x[3], "items": x[4], "deposits": x[5], "banned": x[6] is not None, "ban_reason": x[6] or ""} for x in rows]})
async def h_adm_stats(r):
    uid = auth(r); need_admin(uid)
    c = dict(db.execute("SELECT status,COUNT(*) FROM deposits GROUP BY status").fetchall())
    paid = db.execute("SELECT COALESCE(SUM(total+bonus),0) FROM deposits WHERE status='done'").fetchone()[0]
    pl = db.execute("SELECT COUNT(*) FROM users").fetchone()[0]
    wc = dict(db.execute("SELECT status,COUNT(*) FROM withdrawals GROUP BY status").fetchall())
    dep24, paid24 = db.execute("SELECT COUNT(*),COALESCE(SUM(total+bonus),0) FROM deposits WHERE status='done' AND created>=?", (int(time.time()) - 86400,)).fetchone()
    return J({"dep24": dep24, "paid24": paid24, "new": c.get("new", 0), "contacted": c.get("contacted", 0), "done": c.get("done", 0), "rejected": c.get("rejected", 0), "paid": paid, "players": pl,
              "wd_new": wc.get("new", 0), "wd_active": wc.get("new", 0) + wc.get("contacted", 0), "wd_done": wc.get("done", 0), "wd_rejected": wc.get("rejected", 0),
              "visits": db.execute("SELECT COUNT(*) FROM web_visits").fetchone()[0], "bans": db.execute("SELECT COUNT(*) FROM bans").fetchone()[0], "promos": db.execute("SELECT COUNT(*) FROM promocodes").fetchone()[0], "tts": db.execute("SELECT COUNT(*) FROM tiktokers").fetchone()[0], "dep_on": dep_open(), "wd_on": wd_open(), "bot_on": bot_open(), "depb": len([i for i in dep_block_set() if 0 <= i < len(ITEMS)])})
async def h_adm_give(r):
    uid = auth(r); need_admin(uid); b = await body(r)
    try: pid = int(b.get("id")); amt = int(b.get("amount"))
    except Exception: raise ApiError("Неверные данные")
    if not db.execute("SELECT 1 FROM users WHERE id=?", (pid,)).fetchone(): raise ApiError("Игрок не найден", 404)
    if amt == 0: raise ApiError("Введи сумму (минус в начале — списать)")
    if amt < 0:
        bal = get_user(pid)[0]; take = min(bal, -amt); amt = -take   # в минус не уходим
        if take <= 0: raise ApiError("У игрока уже 0 монет")
    credit(pid, amt); db.commit()
    try: await BOT.send_message(pid, f"🎁 Тебе начислено {amt} 🪙 от админа!" if amt > 0 else f"➖ С твоего баланса списано {-amt} 🪙 админом.")
    except Exception: pass
    return J({"ok": True, "amount": amt})
