    if kind == "bot":
        setting_set("bot_open", "1" if opn else "0")
        if opn: setting_set("bot_msg", "")
    else: setting_set("dep_open" if kind == "dep" else "wd_open", "1" if opn else "0")
    return J({"deposit_on": dep_open(), "withdraw_on": wd_open(), "bot_on": bot_open()})
