async def h_adm_depblock_set(r):
    uid = auth(r); need_admin(uid); b = await body(r)
    ids, blocked = b.get("items"), b.get("blocked")
    if not isinstance(ids, list) or not isinstance(blocked, bool) or len(ids) > len(ITEMS): raise ApiError("Неверные данные")
    for i in ids:
        if not isinstance(i, int) or isinstance(i, bool) or not (0 <= i < len(ITEMS)): continue
        if blocked: db.execute("INSERT OR IGNORE INTO dep_block(item) VALUES(?)", (i,))
        else: db.execute("DELETE FROM dep_block WHERE item=?", (i,))
    db.commit()
    return J({"ok": True, "items": sorted(i for i in dep_block_set() if 0 <= i < len(ITEMS))})
