async def h_adm_wdreq_set(r):
    uid = auth(r); need_admin(uid); b = await body(r)
    ids, dep = b.get("items"), b.get("dep")
    if not isinstance(ids, list) or len(ids) > len(ITEMS): raise ApiError("Неверные данные")
    if dep is not None and (not isinstance(dep, int) or isinstance(dep, bool) or not (0 <= dep <= 10_000_000)): raise ApiError("Депозит — целое число от 0")
    for i in ids:
        if not isinstance(i, int) or isinstance(i, bool) or not (0 <= i < len(ITEMS)): continue
        if dep is None: db.execute("DELETE FROM wd_req WHERE item=?", (i,))
        else: db.execute("INSERT INTO wd_req(item,dep) VALUES(?,?) ON CONFLICT(item) DO UPDATE SET dep=excluded.dep", (i, dep))
    db.commit()
    return await h_adm_wdreq(r)
