    if pid == uid or is_admin(pid): raise ApiError("Админа забанить нельзя")
    db.execute("INSERT INTO bans(user_id,reason,by_admin,ts) VALUES(?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET reason=excluded.reason, by_admin=excluded.by_admin, ts=excluded.ts",
               (pid, reason, uid, int(time.time()))); db.commit()
    try: await BOT.send_message(pid, f"🚫 Ты заблокирован в игре.\nПричина: {reason}")
    except Exception: pass
    return J({"ok": True})
