async def h_adm_deppromo_set(r):
    uid = auth(r); need_admin(uid); b = await body(r)
    code = re.sub(r"\s+", "", str(b.get("code") or "")).upper(); pct = b.get("pct")
    if not re.fullmatch(r"[A-Z0-9_\-]{3,24}", code): raise ApiError("Код: 3–24 символа, латиница, цифры, _ или -")
    if not isinstance(pct, int) or isinstance(pct, bool) or not (1 <= pct <= 100): raise ApiError("Бонус: от 1 до 100%")
    if not db.execute("SELECT 1 FROM dep_promos WHERE code=?", (code,)).fetchone() and (db.execute("SELECT 1 FROM promocodes WHERE code=?", (code,)).fetchone() or db.execute("SELECT 1 FROM tiktokers WHERE ref_code=?", (code,)).fetchone()):
        raise ApiError("Такой код уже занят")
    db.execute("INSERT INTO dep_promos(code,pct,active,created,used) VALUES(?,?,1,?,0) ON CONFLICT(code) DO UPDATE SET pct=excluded.pct", (code, pct, int(time.time()))); db.commit()
    return J({"ok": True, "code": code})
