# --- топ рефералов / партнёры / ссылки партнёра ---
def clean_tg(v):
    v = str(v or "").strip()
    if not v: return None
    v = re.sub(r"^(https?://)?(www\.)?(t\.me|telegram\.me)/", "", v, flags=re.I).lstrip("@").split("?")[0].split("/")[0]
    if not re.fullmatch(r"[A-Za-z0-9_]{4,32}", v): raise ApiError("ТГК: укажи @username канала или ссылку t.me/...")
    return v
def clean_tiktok(v):
    v = str(v or "").strip()
    if not v: return None
    v = re.sub(r"^(https?://)?(www\.|vm\.)?tiktok\.com/", "", v, flags=re.I).lstrip("@").split("?")[0].split("/")[0]
    if not re.fullmatch(r"[A-Za-z0-9_.]{2,24}", v): raise ApiError("TikTok: укажи @username или ссылку на профиль")
    return v

async def h_top_ref(r):
    uid = auth(r)
    rows = db.execute("SELECT r.inviter,u.username,u.name,COUNT(*) c FROM referrals r LEFT JOIN users u ON u.id=r.inviter "
                      "GROUP BY r.inviter ORDER BY c DESC, MIN(r.ts) ASC LIMIT 20").fetchall()
    mine = invited_count(uid)
    rank = (db.execute("SELECT COUNT(*) FROM (SELECT inviter FROM referrals GROUP BY inviter HAVING COUNT(*)>?)", (mine,)).fetchone()[0] + 1) if mine else None
    return J({"top": [{"name": x[2] or (("@" + x[1]) if x[1] else "Игрок"), "count": x[3], "me": x[0] == uid} for x in rows],
              "me": {"count": mine, "rank": rank}})

