def start_tunnel(port):
    """Поднимает бесплатный HTTPS-туннель Cloudflare (нужен Telegram для Mini App)."""
    try:
        exe = shutil.which("cloudflared")
        if exe:
            p = subprocess.Popen([exe, "tunnel", "--url", f"http://127.0.0.1:{port}", "--no-autoupdate"], stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, encoding="utf-8", errors="ignore")
            globals()["_TUN"] = p
            for line in p.stdout:
                m = re.search(r"https://[a-z0-9-]+\.trycloudflare\.com", line)
                if m:
                    threading.Thread(target=lambda: [None for _ in p.stdout], daemon=True).start()
                    return m.group(0)
            return None
        _need("pycloudflared", "pycloudflared")
        from pycloudflared import try_cloudflare
        t = try_cloudflare(port=port)
        return getattr(t, "tunnel", None) or str(t)
    except Exception as e:
        print("⚠️ Не удалось поднять туннель:", e); return None

# ---------- рассылка из админки / бота: журнал + отправка ----------
db.execute("CREATE TABLE IF NOT EXISTS broadcasts(id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER, admin INTEGER, kind TEXT, target INTEGER, target_name TEXT, txt TEXT, total INTEGER, ok INTEGER DEFAULT 0, bad INTEGER DEFAULT 0, status TEXT DEFAULT 'run', via TEXT DEFAULT 'web')"); db.commit()
PLAY_URL = None          # адрес игры для кнопки «Играть» — заполняется при старте бота
BC_MAX = 3500
def bc_ids():
    return [r[0] for r in db.execute("SELECT id FROM users WHERE id>1 AND id NOT IN (SELECT user_id FROM bans)").fetchall()]
def bc_kb(play=True):
    if not play or not PLAY_URL: return None
    from aiogram.types import InlineKeyboardMarkup, InlineKeyboardButton, WebAppInfo
    return InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="🎮 Играть", web_app=WebAppInfo(url=PLAY_URL))]])
def bc_log_start(admin, kind, target, tname, txt, total, via):
    cur = db.execute("INSERT INTO broadcasts(ts,admin,kind,target,target_name,txt,total,via) VALUES(?,?,?,?,?,?,?,?)", (int(time.time()), admin, kind, target, tname, txt, total, via)); db.commit()
    return cur.lastrowid
def bc_log_upd(bid, ok, bad, status=None):
    if status: db.execute("UPDATE broadcasts SET ok=?,bad=?,status=? WHERE id=?", (ok, bad, status, bid))
    else: db.execute("UPDATE broadcasts SET ok=?,bad=? WHERE id=?", (ok, bad, bid))
    db.commit()
def bc_running():
    return db.execute("SELECT 1 FROM broadcasts WHERE status='run' AND kind='all' AND ts>?", (int(time.time()) - 3600,)).fetchone() is not None
async def bc_send_one(uid, text, chat, mid, play):
    from aiogram.exceptions import TelegramRetryAfter
    kb = bc_kb(play)
    for _ in range(3):
        try:
            if chat: await BOT.copy_message(uid, chat, mid, reply_markup=kb)
            else: await BOT.send_message(uid, text, reply_markup=kb)
            return True
        except TelegramRetryAfter as e: await asyncio.sleep(e.retry_after + 1)
        except Exception: return False
    return False
async def bc_run(bid, ids, text, chat=None, mid=None, play=True, progress=None):
    ok = bad = 0
    try:
        for i, uid in enumerate(ids, 1):
            if await bc_send_one(uid, text, chat, mid, play): ok += 1
            else: bad += 1
            if i % 20 == 0:
                bc_log_upd(bid, ok, bad)
                if progress:
                    try: await progress(i, len(ids))
                    except Exception: pass
            await asyncio.sleep(0.05)
        bc_log_upd(bid, ok, bad, "done")
    except Exception as e:
        print("broadcast:", e); bc_log_upd(bid, ok, bad, "fail")
    return ok, bad
async def bc_report(bid, admin, ids, text, play):
    ok, bad = await bc_run(bid, ids, text, None, None, play)
    try: await BOT.send_message(admin, f"📣 Рассылка #{bid} завершена.\nДоставлено: {ok}\nНе доставлено: {bad}")
    except Exception: pass
async def h_adm_bc_list(r):
    uid = auth(r); need_admin(uid)
    rows = db.execute("SELECT id,ts,kind,target,target_name,txt,total,ok,bad,status,via FROM broadcasts ORDER BY id DESC LIMIT 30").fetchall()
    stale = int(time.time()) - 3600
    items = [{"id": x[0], "ts": x[1], "kind": x[2], "target": x[3], "name": x[4], "text": x[5], "total": x[6], "ok": x[7], "bad": x[8], "status": ("fail" if x[9] == "run" and x[1] < stale else x[9]), "via": x[10]} for x in rows]
    return J({"items": items, "recipients": len(bc_ids()), "running": bc_running()})
async def h_adm_bc_send(r):
    uid = auth(r); need_admin(uid); b = await body(r)
    text = str(b.get("text") or "").strip()
    if not text: raise ApiError("Напиши текст сообщения")
    if len(text) > BC_MAX: raise ApiError(f"Слишком длинно (максимум {BC_MAX} символов)")
    play = b.get("play") is not False
    who = str(b.get("who") or "all").strip()
    if who == "all":
        if bc_running(): raise ApiError("Предыдущая рассылка ещё идёт — дождись конца")
        ids = bc_ids()
        if not ids: raise ApiError("Некому отправлять")
        bid = bc_log_start(uid, "all", 0, "", text, len(ids), "web")
        _BG.append(asyncio.create_task(bc_report(bid, uid, ids, text, play)))
        return J({"ok": True, "id": bid, "total": len(ids)})
    who = who.lstrip("@")
    if not who: raise ApiError("Укажи @username или id игрока")
    row = (db.execute("SELECT id,username,name FROM users WHERE id=?", (int(who),)) if who.isdigit() else db.execute("SELECT id,username,name FROM users WHERE LOWER(username)=?", (who.lower(),))).fetchone()
    if not row: raise ApiError("Игрок не найден в базе", 404)
    bid = bc_log_start(uid, "one", row[0], ("@" + row[1]) if row[1] else (row[2] or ("id %s" % row[0])), text, 1, "web")
    ok = await bc_send_one(row[0], text, None, None, play)
    bc_log_upd(bid, 1 if ok else 0, 0 if ok else 1, "done" if ok else "fail")
    if not ok: raise ApiError("Не доставлено: игрок не запускал бота или заблокировал его")
    return J({"ok": True, "id": bid, "total": 1})

# ---------- v23: «Админ-абуз» — раздача награды от админа на время ----------
db.execute("CREATE TABLE IF NOT EXISTS abuse_events(id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, kind TEXT, value INTEGER, max_claims INTEGER, claims INTEGER DEFAULT 0, created INTEGER, ends INTEGER, active INTEGER DEFAULT 1, admin INTEGER)")
db.execute("CREATE TABLE IF NOT EXISTS abuse_claims(event_id INTEGER, user_id INTEGER, ts INTEGER, PRIMARY KEY(event_id,user_id))")
db.commit()
def abuse_prize(kind, value):
    if kind == "coins": return f"{value:,}".replace(",", " ") + " 🪙"
    return ITEMS[value]["name"] if isinstance(value, int) and 0 <= value < len(ITEMS) else "брейнрот"
def abuse_current():
    return db.execute("SELECT id,title,kind,value,max_claims,claims,ends FROM abuse_events WHERE active=1 AND ends>? AND claims<max_claims ORDER BY id DESC LIMIT 1", (int(time.time()),)).fetchone()
def abuse_view(row, uid):
    if not row: return None
    i, title, kind, value, mx, cl, ends = row
    claimed = db.execute("SELECT 1 FROM abuse_claims WHERE event_id=? AND user_id=?", (i, uid)).fetchone() is not None
    return {"id": i, "title": title, "kind": kind, "prize": abuse_prize(kind, value), "left": max(0, mx - cl), "max": mx, "secs": max(0, ends - int(time.time())), "claimed": claimed}
def do_abuse_claim(uid, eid):
    if not isinstance(eid, int) or isinstance(eid, bool): raise ApiError("Событие не найдено", 404)
    if db.execute("SELECT 1 FROM bans WHERE user_id=?", (uid,)).fetchone(): raise ApiError("Аккаунт заблокирован", 403)
    ev = db.execute("SELECT kind,value FROM abuse_events WHERE id=?", (eid,)).fetchone()
    if not ev: raise ApiError("Событие не найдено", 404)
    get_user(uid)
    if db.execute("SELECT 1 FROM abuse_claims WHERE event_id=? AND user_id=?", (eid, uid)).fetchone(): raise ApiError("Ты уже забрал награду в этом абузе")
    now = int(time.time())
    if db.execute("UPDATE abuse_events SET claims=claims+1 WHERE id=? AND active=1 AND ends>? AND claims<max_claims", (eid, now)).rowcount != 1:
        raise ApiError("Опоздал — абуз закончился или награду уже разобрали")
    db.execute("INSERT INTO abuse_claims(event_id,user_id,ts) VALUES(?,?,?)", (eid, uid, now))
    kind, value = ev
    if kind == "coins": credit(uid, value)
    else: add_item(uid, value, 1)
    db.commit()
    return {"ok": True, "prize": abuse_prize(kind, value), "state": get_state(uid)}
async def h_abuse(r):
    uid = auth(r); return J({"event": abuse_view(abuse_current(), uid)})
async def h_abuse_claim(r):
    uid = auth(r); b = await body(r); return J(do_abuse_claim(uid, b.get("id")))
async def h_adm_abuse_list(r):
    uid = auth(r); need_admin(uid); now = int(time.time())
    rows = db.execute("SELECT id,title,kind,value,max_claims,claims,created,ends,active FROM abuse_events ORDER BY id DESC LIMIT 15").fetchall()
    return J({"items": [{"id": x[0], "title": x[1], "prize": abuse_prize(x[2], x[3]), "max": x[4], "claims": x[5], "created": x[6], "secs": max(0, x[7] - now), "live": bool(x[8]) and x[7] > now and x[5] < x[4]} for x in rows]})
def _abint(v, lo, hi, msg):
    if not isinstance(v, int) or isinstance(v, bool) or not (lo <= v <= hi): raise ApiError(msg)
    return v
async def h_adm_abuse_start(r):
    uid = auth(r); need_admin(uid); b = await body(r)
    kind = b.get("kind")
    if kind not in ("coins", "item"): raise ApiError("Выбери тип награды")
    value = _abint(b.get("value"), 1, 100000, "Монет: от 1 до 100 000") if kind == "coins" else _abint(b.get("value"), 0, max(0, len(ITEMS) - 1), "Выбери брейнрота")
    mx = _abint(b.get("max_claims"), 1, 10000, "Мест: от 1 до 10 000")
    mins = _abint(b.get("minutes"), 1, 1440, "Время: от 1 до 1440 минут")
    title = str(b.get("title") or "").strip()[:40] or "Админ-абуз!"
    if abuse_current(): raise ApiError("Уже идёт админ-абуз — сначала останови его")
    now = int(time.time())
    cur = db.execute("INSERT INTO abuse_events(title,kind,value,max_claims,claims,created,ends,active,admin) VALUES(?,?,?,?,0,?,?,1,?)", (title, kind, value, mx, now, now + mins * 60, uid)); db.commit()
    res = {"ok": True, "id": cur.lastrowid}
    if b.get("notify") is True and BOT is not None and not bc_running():
        ids = bc_ids()
        if ids:
            text = f"🎉 {title}\n🎁 Награда: {abuse_prize(kind, value)}\n👥 Мест: {mx} · ⏱ {mins} мин\n\nЖми «Играть» и забирай — кто успел, тот и съел!"
            bid = bc_log_start(uid, "all", 0, "", text, len(ids), "web")
            _BG.append(asyncio.create_task(bc_report(bid, uid, ids, text, True))); res["notified"] = len(ids)
    return J(res)
async def h_adm_abuse_stop(r):
    uid = auth(r); need_admin(uid)
    db.execute("UPDATE abuse_events SET active=0 WHERE active=1"); db.commit(); return J({"ok": True})

_BG = []
async def check_public(url):
    import urllib.request
    def probe():
        try:
            rq = urllib.request.Request(url.rstrip("/") + "/api/ping", headers={"User-Agent": "Mozilla/5.0"})
            with urllib.request.urlopen(rq, timeout=8) as r: return r.status == 200
        except Exception: return False
    for _ in range(12):
        if await asyncio.to_thread(probe):
            print("✅ Публичный адрес отвечает — телефон должен открыть игру"); return
        await asyncio.sleep(4)
    print(f"❌ Публичный адрес не отвечает с этого ПК (~50 сек): {url}\n   Если на телефоне игра не открывается — проверь интернет/туннель и перезапусти скрипт (адрес туннеля меняется при каждом запуске).")


# ---------- v23: автоматические резервные копии базы ----------
BACKUP_EVERY = 6 * 3600     # как часто делать копию (сек)
BACKUP_KEEP = 28            # сколько последних копий хранить (папка backups/)
async def backup_loop():
    """Раз в 6 часов (и сразу при запуске) копирует game.db в папку backups/ — данные игроков не потеряются."""
    os.makedirs("backups", exist_ok=True)
    while True:
        try:
            name = os.path.join("backups", "game_" + time.strftime("%Y%m%d_%H%M%S") + ".db")
            dst = sqlite3.connect(name)
            try: db.backup(dst)
            finally: dst.close()
            files = sorted(f for f in os.listdir("backups") if f.startswith("game_") and f.endswith(".db"))
            for f in files[:-BACKUP_KEEP]:
                try: os.remove(os.path.join("backups", f))
                except Exception: pass
        except Exception as e: print("⚠️ backup:", e)
        await asyncio.sleep(BACKUP_EVERY)

_TUN = None
_RUNNER = None
async def keepalive(own):
    """Сторож: раз в 45 сек стучится на публичный адрес (туннель не засыпает, даже если игроков нет)
    и, если адрес перестал отвечать, сам перезапускает туннель и обновляет кнопку «Играть»."""
    import urllib.request
    def probe(u):
        try:
            rq = urllib.request.Request(u.rstrip("/") + "/api/ping", headers={"User-Agent": "Mozilla/5.0"})
            with urllib.request.urlopen(rq, timeout=12) as r: return r.status == 200
        except Exception: return False
    bad = 0
    while True:
        try:
            await asyncio.sleep(45)
            cur = globals().get("PLAY_URL")
            if cur and await asyncio.to_thread(probe, cur):
                bad = 0; continue
            if not own:
                if cur: print("⚠️ Свой адрес из url.txt не отвечает — проверь, что он включён")
                continue
            bad += 1
            if cur and bad < 3: continue
            print("🔁 Туннель не отвечает — перезапускаю...")
            t = globals().get("_TUN")
            try:
                if t and t.poll() is None: t.terminate()
            except Exception: pass
            new = await asyncio.to_thread(start_tunnel, PORT)
            if not new: print("⚠️ Туннель пока не поднялся, попробую ещё раз"); continue
            globals()["PLAY_URL"] = new; bad = 0
            try:
                from aiogram.types import MenuButtonWebApp, WebAppInfo
                await BOT.set_chat_menu_button(menu_button=MenuButtonWebApp(text="🎮 Играть", web_app=WebAppInfo(url=new)))
            except Exception as e: print("menu button:", e)
            print("✅ Туннель перезапущен:", new)
            try: await notify_admin("🔁 Туннель перезапущен, адрес игры сменился:\n" + new)
            except Exception: pass
        except asyncio.CancelledError: raise
        except Exception as e: print("keepalive:", e)

async def main():
    """Запуск с защитой: ошибка внутри не роняет процесс, а освобождает порт и туннель."""
    try: await _main()
    finally:
        r = globals().get("_RUNNER")
        if r is not None:
            try: await r.cleanup()
            except Exception: pass
            globals()["_RUNNER"] = None
        t = globals().get("_TUN")
        try:
            if t and t.poll() is None: t.terminate()
        except Exception: pass

